      "id": "modern-c05-l26-p01-089",
      "title": "北欧とNATO・2023年9月の補足",
      "body": [
        "さらに、ロシアがウクライナに軍事侵攻したことで、これまで中立の立場をとっていた<strong class=\"source-bold\">北欧のフィンランドとスウェーデン</strong>がロシアの軍事侵攻を警戒して<strong class=\"source-bold\"><ruby>NATO<rt>ナトー</rt></ruby>への加盟</strong>に傾くなど（フィンランドは2023年4月に正式加盟、スウェーデンの加盟も実現する見込み［2023年9月現在］）、ヨーロッパの国際関係に変化が生じているね。"
      ],
      "plainBody": [
        "さらに、ロシアがウクライナに軍事侵攻したことで、これまで中立の立場をとっていた北欧のフィンランドとスウェーデンがロシアの軍事侵攻を警戒してNATOへの加盟に傾くなど（フィンランドは2023年4月に正式加盟、スウェーデンの加盟も実現する見込み［2023年9月現在］）、ヨーロッパの国際関係に変化が生じているね。"
      ],
