      "title": "1987年の単一欧州議定書",
      "body": [
        "1973年以降、どんどん加盟国が増えたEC（表<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.410</strong></span>）では1987年<strong class=\"source-bold\">単一欧州<ruby>議定書<rt>ぎていしょ</rt></ruby></strong>で「1992年までに<strong class=\"source-bold\">ECが完全市場統合を目指す</strong>！」って合意し、市場統合のあとのヨーロッパの統合についての話し合いが始まった。"
      ],
