      "title": "G20の参加国と金融危機への協調",
      "body": [
        "G20とは、これまでの<strong class=\"source-bold\">G7（米・英・日・仏・独・伊・カナダ）</strong>に、<strong class=\"source-bold\"><ruby>BRICS<rt>ブリックス</rt></ruby>（ブラジル・ロシア・インド・中国・南アフリカ）</strong>や、韓国、サウジアラビア、インドネシア、トルコなどを加えたもので、2008年に開かれた第1回首脳会談では、金融危機への対応で協調することを確認したんだ。"
      ],
