        "<strong class=\"source-bold\">フランス</strong>や<strong class=\"source-bold\">中国</strong>は「米ロはこれまで何度も実験をしてきたじゃないか！」と反発し、<strong class=\"source-bold\">国連総会でCTBTが採択される直前</strong>の1995年に、駆け込みで<strong class=\"source-bold\">核実験</strong>をおこなったんだ。"
