      "body": [
        "また、<strong class=\"source-bold\">核兵器の拡散</strong>も問題だよね。インドの核保有に反発した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>が1998年に<strong class=\"source-bold\">核保有国になった</strong>話はすでにしたけど、それ以外にも核開発が問題になっている国があるよ。まずは<strong class=\"source-bold\">イラン</strong>だ。"
      ],
