      "title": "米国の批准拒否と2005年の発効",
      "body": [
        "でも、新興国に制限がなかったことから、反発した<strong class=\"source-bold\">アメリカは<ruby>批准<rt>ひじゅん</rt></ruby>を拒否</strong>した。当時、CO₂の排出量の上位2国はアメリカと中国だったから、その両国の協力がないと、世界全体での削減は難しいよね（<strong class=\"source-bold\">京都議定書は2004年にロシアが批准して、2005年に発効</strong>）。"
      ],
      "plainBody": [
        "でも、新興国に制限がなかったことから、反発したアメリカは批准を拒否した。当時、CO₂の排出量の上位2国はアメリカと中国だったから、その両国の協力がないと、世界全体での削減は難しいよね（京都議定書は2004年にロシアが批准して、2005年に発効）。"
      ],
