      "title": "2015年のパリ協定と2016年の発効",
      "body": [
        "その後も先進国と新興国の対立が続いたんだけど、2015年の<strong class=\"source-bold\">パリ会議【COP21】</strong>では、京都議定書以来の新たな枠組みとなる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ協定</strong></span>が採択され、<strong class=\"source-bold\">途上国も含めたすべての国の温室効果ガス削減目標</strong>を定めることになったんだ（2016年に発効）。"
      ],
