      "title": "ユーゴスラヴィアの成立",
      "body": [
        "そもそも、第一次世界大戦後に成立した時点で、<strong class=\"source-bold\">ユーゴスラヴィア（ユーゴ）</strong>は統一することに無理がある国だった。"
      ],
