      "id": "modern-c05-l26-p03-007",
      "title": "1991年6月の独立宣言と連邦軍介入",
      "body": [
        "1991年6月、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スロヴェニア共和国</strong></span>（<strong class=\"source-bold\">カトリック</strong>）と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クロアティア共和国</strong></span>（<strong class=\"source-bold\">カトリック</strong>）が独立を宣言すると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>（セルビア正教会）を中心とする<strong class=\"source-bold\">ユーゴ連邦軍が軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア内戦</strong></span>が始まった。"
      ],
