      "id": "modern-c05-l26-p03-030",
      "title": "入植・隔離と報復の応酬",
      "body": [
        "だって、イスラエルは<strong class=\"source-bold\">パレスチナ人指導者の暗殺</strong>や<strong class=\"source-bold\">パレスチナ人地域への新たな入植、パレスチナ人自治区の<ruby>隔離<rt>かくり</rt></ruby></strong>（通称“<strong class=\"source-bold\"><ruby>壁<rt>かべ</rt></ruby></strong>”の建設）などの強行策を続けたんだもん。しかも、パレスチナ側も<strong class=\"source-bold\"><ruby>自爆<rt>じばく</rt></ruby>テロで対抗</strong>したから、報復に次ぐ報復で和平はどんどん遠のいている。"
      ],
