        "だって、イスラエルはパレスチナ人指導者の暗殺やパレスチナ人地域への新たな入植、パレスチナ人自治区の隔離（通称“壁”の建設）などの強行策を続けたんだもん。しかも、パレスチナ側も自爆テロで対抗したから、報復に次ぐ報復で和平はどんどん遠のいている。"
