      "title": "湾岸戦争時の財政支援",
      "body": [
        "<span class=\"source-japan-frame\">1991年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>湾岸<rt>わんがん</rt></ruby>戦争</strong></span>では、国連<strong class=\"source-bold\">安保理の決議に基づく多国籍軍を派遣</strong>したけど、憲法の規定で<strong class=\"source-bold\">海外への自衛隊派兵が難しかった日本</strong>は、130億ドルも<strong class=\"source-bold\">財政支援をした</strong>んだけど、戦後に評価はされなかった。</span>"
      ],
