export const sourcePages = {
  "476": "<h2>476</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">冷戦終結後の世界</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">（1990〜）</span></h1>\n<p>さあ、いよいよ最終回まできたね。最後は、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>冷戦<rt>れいせん</rt></ruby>終結後の欧米諸国</strong></u>を中心に、現代の世界で起きている問題を見ていくよ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td></tr><tr><td><strong class=\"source-bold\">冷戦終結後の欧米諸国</strong></td><td><strong class=\"source-bold\">現代の諸問題</strong></td><td><strong class=\"source-bold\">地域紛争・民族紛争の激化</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">477〜485ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">486〜491ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">491〜496ページ</span></td></tr></tbody></table></div>\n<blockquote><p>いよいよ最終回！ 特に、早慶など最上位の私立大学では、必須の冷戦終結後だ！</p></blockquote>\n<p>冷戦が終わって唯一の超大国になった<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカ</strong></u>は、国際社会との連携よりも「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">単独行動主義</strong></u>」が目立ち始める。一方の<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ロシア</strong></u>は、国内の<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">民族問題</strong></u>が深刻だね。ヨーロッパも<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ECからEU</strong></u>になって統合が進んだけど、加盟国が増えすぎて、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イギリスの離脱</strong></u>などの問題も起きているよね。それから、冷戦終結後に起きた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">経済危機</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>核<rt>かく</rt></ruby>開発問題</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">民族<ruby>紛争<rt>ふんそう</rt></ruby></strong></u>……最後は、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ロシアのウクライナ<ruby>侵攻<rt>しんこう</rt></ruby></strong></u>や<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">米中新冷戦</strong></u>、さらに<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">環境問題</strong></u>まで解説していくよ。ここ最近は、早慶などの難関大などを中心に、冷戦終結後まで普通に出題してくるから、最後のツメと思って、しっかり確認してね！</p>\n<p>それじゃあ、いよいよ最終回、冷戦終結後の世界の始まり〜。</p>",
  "477": "<h2>477</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦終結後の欧米諸国</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-background=\"white\" data-source-border=\"red\" data-source-border-pattern=\"diagonal-lines\" style=\"border:1px solid #e52715;background:repeating-linear-gradient(135deg,#fff 0 4px,#fbe1e1 4px 5px);padding:0 0.2em\"><strong class=\"source-bold\">冷戦終結後の欧米諸国</strong></span></h3>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈アメリカ合衆国〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ブッシュ（父）大統領は、唯一の超大国として<ruby>湾岸<rt>わんがん</rt></ruby>戦争を主導！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷戦終結を宣言</strong></span>した共和党の大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">父</strong></span>）<strong class=\"source-bold\">【</strong>G.H.W. ブッシュ<strong class=\"source-bold\">】</strong>は、「アメリカが<strong class=\"source-bold\">冷戦に勝利した唯一の超大国</strong>」という自信を持って、「アメリカの価値観、“自由と民主主義”にあわない国は<ruby>潰<rt>つぶ</rt></ruby>す」と考え始めた。これは、<strong class=\"source-bold\">彼の息子（のちのブッシュ大統領ね）にも影響する考え方</strong>だ。まず、1989年にはノリエガ軍事政権の打倒を口実に<strong class=\"source-bold\">パナマに軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong>した。まあ、ホンネでは<strong class=\"source-bold\">パナマ運河を返したくなかった</strong>からだけどさ。</p>\n<blockquote><p>現職大統領が大統領選挙で負けたのは、戦後だとフォード、カーター、ブッシュ（父）の3人だけだよ……</p></blockquote>\n<p>そして1991年には、<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>決議に基づいて</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">湾岸戦争</strong></span>を起こした。攻撃したのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">多国籍軍</strong></span>だけど、<strong class=\"source-bold\">指導権を握ったのはアメリカ</strong>だ。そして、戦勝ムードで一時的に支持率を高めたものの、戦費による<strong class=\"source-bold\">急激な財政の悪化</strong>と国内の景気後退で人気を落とし、2期目の大統領選挙では若いクリントンに負けちゃったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 民主党大統領クリントンは、平和外交と財政再建で好景気に！</strong></span></h4>\n<p>レーガン、ブッシュ（父）と続いた共和党の強硬路線から一転、<strong class=\"source-bold\">民主党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリントン</strong></span>大統領は<strong class=\"source-bold\">平和的な外交</strong>を進めたよ。彼はケネディにあこがれて政治家になったんだ。まず、就任した年［1993］に、<strong class=\"source-bold\">中東和平の保証人</strong>として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ<ruby>暫定<rt>ざんてい</rt></ruby>自治協定</strong></span>の<ruby>締結<rt>ていけつ</rt></ruby>に立ち会い、さらに1995年にはユーゴスラヴィア問題にも介入して、<strong class=\"source-bold\">ボスニア和平協定</strong>の締結を仲介したよ。こうした平和外交とあわせて<strong class=\"source-bold\">財政再建と景気の回復</strong>を狙い、<strong class=\"source-bold\">アメリカ・カナダ・メキシコ</strong>で自由貿易圏をつくる<strong class=\"source-bold\">北米自由貿易協定【<ruby>NAFTA<rt>ナフタ</rt></ruby>】</strong>にも調印した。さらには、同じ民主党のカーターが結んだ<strong class=\"source-bold\">新パナマ運河条約を守り</strong>、1999年末に<strong class=\"source-bold\">パナマ運河を返還</strong>したんだ。こうした平和外交で軍事費を抑えて財政を再建したよ。</p>\n<blockquote><p>クリントンの奥さんヒラリーはむちゃくちゃ頭が良い！ クリントン政権でも、<strong class=\"source-bold\">重要な政策</strong>にかかわっていたよ</p></blockquote>\n<p>そして、経済的には<strong class=\"source-bold\">クリントン時代のアメリカは史上空前の好景気</strong>。背景はいくつかあるよ。まずは、<strong class=\"source-bold\">インターネットの開放</strong>でパソコンが爆発的に普及して、アップルやマイクロソフトなどの<strong class=\"source-bold\">IT企業が急成長</strong>してアメリカ経済を押し上げた、いわゆる<strong class=\"source-bold\">IT（インターネット）バブル</strong>だよ。さらに、<strong class=\"source-bold\">NAFTAの成立が貿易拡大にもつながった</strong>からね。ただ任期の後半には、女性スキャ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "478": "<h2>478</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>ンダル（不倫問題）から批判を受けて議会で追及された日に、<ruby>NATO<rt>ナトー</rt></ruby><strong class=\"source-bold\">軍にセルビア空爆を命令</strong>してコソヴォ問題に<ruby>介入<rt>かいにゅう</rt></ruby>するなど、一貫性のない外交も多少は問題になったけど、最後まで人気があったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ブッシュ（子）大統領は、国連を軽視した単独行動主義に突っ走る！</strong></span></h4>\n<p>そして2000年の大統領選挙は、まれにみる接戦の末、<strong class=\"source-bold\">共和党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">子</strong></span>）<strong class=\"source-bold\">【</strong>G.W. ブッシュ<strong class=\"source-bold\">】</strong>が当選したけど、就任後はあまり人気がなかった。それを一気に変えたのが、2001年に起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">同時多発テロ事件</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">9.11事件</strong></span>】</strong>だ。<strong class=\"source-bold\">ニューヨークの世界貿易センタービルにハイジャックされた飛行機が突っ込み</strong>、さらにワシントン郊外の国防総省にも同じように旅客機が激突した。史上初めて<strong class=\"source-bold\">アメリカ本土</strong>の、<strong class=\"source-bold\">しかも<ruby>中枢<rt>ちゅうすう</rt></ruby>であるニューヨークを攻撃</strong>されたアメリカ人はヒステリックになった。ブッシュ大統領も「<strong class=\"source-bold\">テロとの戦い（対テロ戦争）</strong>」をおこなうと宣言、この事件の首謀者をイスラーム原理主義のテロ組織<strong class=\"source-bold\">アル＝カーイダ</strong>の指導者<strong class=\"source-bold\">ビン＝ラーディン</strong>だと断定し、アル＝カーイダを支援する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフガニスタンを攻撃</strong></span>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ターリバーン政権</strong></span>を崩壊させたんだ。</p>\n<blockquote><p>同時多発テロ事件の直後に歴代最高の支持率（90％！）を記録したけど、任期の最後には史上最低（19％らしい……）まで落ちた……極端だな</p></blockquote>\n<p>その後もアメリカは、所在不明になっているビン＝ラーディンを捕まえるために戦闘を続けたから、アフガニスタンではテロとゲリラ戦の<ruby>応酬<rt>おうしゅう</rt></ruby>で大混乱になった。さらに、テロを支援する国として、<strong class=\"source-bold\">イラン・イラク・北朝鮮</strong>を「<strong class=\"source-bold\">悪の<ruby>枢軸<rt>すうじく</rt></ruby></strong>」と名指しで批判し、2003年には<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>決議のないまま</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米英軍でイラクを攻撃</strong></span>した。こうして始まった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラク戦争</strong></span>にはオーストラリアも派兵し、<strong class=\"source-bold\">日本も<ruby>小泉<rt>こいずみ</rt></ruby>首相が武力行使を支持</strong>したけど、<strong class=\"source-bold\">中国・ロシア・フランス・ドイツ</strong>などはアメリカの<strong class=\"source-bold\">単独行動主義</strong>を非難したんだ。</p>\n<p>そして、ブッシュ政権を揺るがしたのが、2008年の<strong class=\"source-bold\">世界金融危機【</strong>リーマン＝ショック<strong class=\"source-bold\">】</strong>だよ。経済危機に有効な手段を打ち出せないまま、<strong class=\"source-bold\">増え続ける軍事費への批判</strong>が強まり、アメリカ人は「ブッシュ大統領の任期が終われば、世界は良くなる」とまで言い始めた。こりゃ、次の大統領選挙は誰が出ても民主党の勝ちだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アメリカ史上初の黒人大統領オバマは、ブッシュ時代からの転換を目指す</strong></span></h4>\n<p>2008年の大統領選挙では民主党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オバマ</strong></span>が当選し、<strong class=\"source-bold\">アメリカ史上初のアフリカ系（黒人）大統領</strong>になった。彼はブッシュの時代にバラバラになった国内の<ruby>融和<rt>ゆうわ</rt></ruby>と、さまざまな国際対立を引き起こした「単独行動主義」から「<strong class=\"source-bold\">国際協調主義</strong>」への転</p>",
  "479": "<h2>479</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦終結後の欧米諸国</u></p></blockquote>\n<p>換を図った。就任後（2009）にはトルコやエジプトでの演説で「<strong class=\"source-bold\">イスラームとの和解</strong>」を、さらにチェコでは「<strong class=\"source-bold\"><ruby>核<rt>かく</rt></ruby>兵器なき世界</strong>」を目指すという<strong class=\"source-bold\">プラハ演説【核兵器廃絶演説】</strong>を発表し、この年のノーベル平和賞を受賞したんだ。とはいえ、本人も受賞のスピーチで語ったように「まだ何もしていない」状態での受賞だったから、翌年には<strong class=\"source-bold\">ロシア</strong>との交渉をまとめ、<strong class=\"source-bold\">メドヴェージェフ</strong>大統領と<strong class=\"source-bold\">第4次戦略兵器削減条約【新<ruby>START<rt>スタート</rt></ruby>】</strong>に調印したんだ。</p>\n<p>一方、中東問題では、まず<strong class=\"source-bold\">アフガニスタン</strong>に軍を増派して、2011年5月にはアル＝カーイダの指導者<strong class=\"source-bold\">ビン＝ラーディンを<ruby>拘束<rt>こうそく</rt></ruby>して殺害</strong>した。その後、2011年12月には、イラクから米軍を完全撤退させて<strong class=\"source-bold\">イラク戦争の終結</strong>を宣言した。ただ、中東に広がった革命運動、いわゆる「<strong class=\"source-bold\">アラブの春</strong>」への対応は後手に回ることが多く、2011年には<strong class=\"source-bold\">リビア</strong>で民主化運動を弾圧した<strong class=\"source-bold\">カダフィ政権を攻撃</strong>したり、2014年にはシリア内戦にも介入し、イラク北部とシリアに拡大した武装集団「<strong class=\"source-bold\">イスラーム国【IS</strong>（Islamic State）<strong class=\"source-bold\">】</strong>」を空爆した。</p>\n<p>一方で、<strong class=\"source-bold\">キューバとは国交正常化</strong>したよ。これは、キューバ革命後にアイゼンハワー大統領が国交を断絶して以来だね。</p>\n<p>国内問題では、2010年に民主党の悲願だった<ruby>貧困<rt>ひんこん</rt></ruby>層向けの<strong class=\"source-bold\">医療保険制度改革</strong>（オバマ・ケア）を実現したんだけど、成立後も<strong class=\"source-bold\">共和党は反対の立場</strong>をとるなど、アメリカ社会の分断が明らかになり始めたんだ。</p>\n<p>そして、任期中には気候変動に関するパリ協定の議論を推進したり、現職大統領として初めてキューバ、アフリカ連合、そして<strong class=\"source-bold\">被爆地である広島を訪問</strong>したことなどから、アメリカの国際的な評価を向上させたよ。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ トランプ大統領の登場で、国内や世界の分断が加速！</strong></span></h4>\n<p>アメリカ社会の分断は、2017年の大統領選挙でより鮮明となり、「<strong class=\"source-bold\">アメリカ第一主義</strong>」を掲げた共和党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トランプ</strong></span>が当選したんだ。トランプ大統領はとにかく、目先でアメリカが「得」と判断したことを強行したよ。国内産業の保護や移民の受け入れ制限などグローバル化からは一線を引き、国際協調を拒否してさまざまな合意や条約を次々と破棄。すでに合意していた<strong class=\"source-bold\">TPPからは離脱</strong><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">➡P.453</strong></span>、ロシアとの<strong class=\"source-bold\">中距離核戦力全廃条約も破棄</strong>、地球温暖化抑止のための<strong class=\"source-bold\">パリ協定からも離脱</strong>して、さらに北米自由貿易協定【<ruby>NAFTA<rt>ナフタ</rt></ruby>】もより保護主義的なUAMCA <strong class=\"source-bold\">【アメリカ＝メキシコ＝カナダ協定】</strong>へと変えたんだ。</p>\n<p>こうした「<strong class=\"source-bold\">アメリカ第一主義</strong>」は<strong class=\"source-bold\">同盟国との関係をギクシャクさせ</strong>、これまでアメリカが支えてきた世界秩序を自ら変えることになる。そこに付け込んで<strong class=\"source-bold\">勢力拡大を狙ったのが<ruby>習近平<rt>しゅうきんぺい</rt></ruby>体制の中国</strong>だよ。お互いに保護関税を掛け合う貿易戦争となったり、アメリカが一歩引いている隙を狙って、中国が各地に経済的・軍事的な影響力を強めていったんだ<span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">➡P.489</strong></span>。一方で、北朝鮮の<ruby>金正恩<rt>キムジョンウン</rt></ruby>との<strong class=\"source-bold\">史上初の米朝首脳会談</strong>をおこなうなど、独自の動きも見せたけど、具体的な成果はなかったね。</p>\n<p>また<strong class=\"source-bold\">国内の分断も深刻</strong>だ。トランプを支持する白人保守層と民主党を支持す</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "480": "<h2>480</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>るリベラル派との対立は根深く、女性差別に反対する「<strong class=\"source-bold\">Me Too</strong>」<strong class=\"source-bold\">運動</strong>や黒人差別に反対する「<strong class=\"source-bold\">BLM</strong>（Black Lives Matter）」<strong class=\"source-bold\">運動</strong>などが高揚する一方、トランプ支持者が連邦議会を襲撃するなど、民主主義を脅かす事件まで起きたんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「脱トランプ」を図るバイデン大統領は、国際協調路線に転換！</strong></span></h4>\n<p>アメリカや世界の分断が進むなか、2020年の大統領選挙では<strong class=\"source-bold\">民主党</strong>の<strong class=\"source-bold\">バイデン</strong>が当選したよ。バイデン大統領は、トランプ政権が壊してしまった同盟国との関係を再構築し、<strong class=\"source-bold\">パリ協定にも復帰</strong>してヨーロッパ諸国と協調して脱二酸化炭素社会に向けて舵を切ったんだ。</p>\n<p>ただ、国際的には<strong class=\"source-bold\">中国をアメリカの<ruby>覇権<rt>はけん</rt></ruby>を脅かす挑戦者とみなして対立を深め（米中新冷戦）</strong>、またロシアのウクライナ<ruby>侵攻<rt>しんこう</rt></ruby>に対しては、<strong class=\"source-bold\">西欧諸国と協調してウクライナを支援</strong>してロシアに対する制裁をおこなっているね。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈ロシア〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連<ruby>崩壊<rt>ほうかい</rt></ruby>後も国内の民族問題は消えず、歴代大統領の強権政治が続く</strong></span></h4>\n<p>ロシアは、崩壊したソ連の国際的な地位を引き継ぎ、<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>の常任理事国</strong>となった。ただロシアの政局は安定せず、体制改革をめぐる対立から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エリツィン</strong></span>大統領が<strong class=\"source-bold\">軍を出動させて議会を攻撃</strong>するなど、強権的な政治が続いたんだ。</p>\n<p>さらにロシアを悩ませたのは<strong class=\"source-bold\">少数民族の独立問題</strong>、特に黒海とカスピ海の間に位置する<strong class=\"source-bold\">チェチェン</strong>の問題だ。1991年に<strong class=\"source-bold\">チェチェンがロシア連邦からの独立を宣言</strong>すると、独立を認めないロシア連邦が軍事<ruby>介入<rt>かいにゅう</rt></ruby>して、1994年に<strong class=\"source-bold\">チェチェン紛争</strong>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>した。これはもちろんチェチェンの民族運動が原因だけど、同時にロシアは中央アジアで採った<strong class=\"source-bold\">石油をヨーロッパに運ぶパイプライン</strong>のルートの利権を確保するため、チェチェンを独立させるわけにはいかない、って事情もあった。さらにチェチェン紛争は、何度か停戦に合意しても、反抗する<strong class=\"source-bold\">イスラーム武装勢力がテロ攻撃</strong>をおこなったり、<strong class=\"source-bold\">ロシア側も和平提案と攻撃を繰り返した</strong>りと、泥沼化していったんだ。そして、首都モスクワでも爆弾テロなどが続いたため、首相の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プーチン</strong></span>が<strong class=\"source-bold\">強硬な軍事作戦</strong>を進めて人気を高め、1999年に健康問題などから辞任したエリツィンにかわって</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ウクライナ</strong></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">ロシア</strong></span></td><td><strong class=\"source-bold\">カザフスタン</strong></td></tr><tr><td><em>黒海</em></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">チェチェン紛争</span></td><td><em>カスピ海</em></td></tr><tr><td><strong class=\"source-bold\">トルコ</strong></td><td><strong class=\"source-bold\">ジョージア（グルジア）</strong></td><td><strong class=\"source-bold\">トルクメニスタン</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">アゼルバイジャン</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">バクー沖油田</span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">━</span></td><td>ロシアが引きたい石油パイプラインのルート</td></tr></tbody></table></div>\n<blockquote><p>バクー沖油田からのパイプラインの利権のため、ロシアはチェチェンの独立を<ruby>潰<rt>つぶ</rt></ruby>すんだ！</p></blockquote>",
  "481": "<h2>481</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦終結後の欧米諸国</u></p></blockquote>\n<p>大統領代行となると、2000年の選挙でも当選して大統領となった。</p>\n<p><strong class=\"source-bold\">プーチンが大統領になったあともチェチェン紛争は続き</strong>、ロシアでは反発した武装勢力のテロやゲリラが続いたんだ。2002年の<strong class=\"source-bold\">モスクワの劇場<ruby>占拠<rt>せんきょ</rt></ruby>事件</strong>や2004年の<strong class=\"source-bold\">北オセチア学校占拠事件</strong>では、プーチン政権が軍や武装警察を出動して<ruby>鎮圧<rt>ちんあつ</rt></ruby>したから、人質となった一般市民や生徒が犠牲になった。こんなふうに、プーチンはかなり強権的な政治で権力を安定させたんだよ。彼はもともと<strong class=\"source-bold\">旧ソ連スパイ組織KGBの出身</strong>だからね。いろいろ危ないことも知ってるんだろうか……。</p>\n<p>そして2008年、<strong class=\"source-bold\">メドヴェージェフ</strong>が大統領になったけど、<strong class=\"source-bold\">プーチンはそのまま実権を握り</strong>、2012年には<strong class=\"source-bold\">再びプーチンが大統領になった</strong>。2009年には<strong class=\"source-bold\">チェチェン紛争の終結が宣言された</strong>けど、その後も爆弾テロなどが続いている。また、チェチェンと同じように石油パイプラインの建設をめぐり、今度はロシアが<strong class=\"source-bold\">ジョージア</strong>（グルジア）領内の<strong class=\"source-bold\">南オセチア州の独立運動</strong>に介入、2008年にはロシアとジョージアが武力衝突した（<strong class=\"source-bold\">南オセチア紛争</strong>）。</p>\n<p>そして2014年、<strong class=\"source-bold\">プーチン</strong>はウクライナ領の<strong class=\"source-bold\">クリミア半島</strong>（クリミア自治共和国）の<ruby>併<rt>へい</rt></ruby><ruby>合<rt>ごう</rt></ruby>を一方的に宣言したよ。クリミア半島には、かつてのロシア帝国、ソ連、さらにソ連崩壊後のロシアも<strong class=\"source-bold\">海軍基地を置いていた</strong>し、ロシア人、ウクライナ人、そしてクリミア＝タタール人の間で、民族的な<ruby>軋轢<rt>あつれき</rt></ruby>が強まっていたからね。プーチンはクリミアで強行した住民投票で賛成を得たとしてこの地を併合し、さらに<strong class=\"source-bold\">ウクライナ東部に軍を進めた</strong>。ただ、この時はドイツやフランスなども立ち会って、いったん停戦合意が成立したけど、ロシアに対する制裁が始まり、<strong class=\"source-bold\">ロシアはG8への参加資格を失った</strong>んだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ポーランド</strong></td><td><strong class=\"source-bold\">ベラルーシ</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span></td></tr><tr><td></td><td><strong class=\"source-bold\">キーウ【キエフ】</strong></td><td><span data-source-color=\"gray-green\" style=\"color:#859476\">ドニエプル川</span></td></tr><tr><td><strong class=\"source-bold\">モルドヴァ</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウクライナ</strong></span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウクライナ侵攻（2022〜）</strong></span></span></td></tr><tr><td><strong class=\"source-bold\">ルーマニア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア半島併合（2014）</strong></span></span></td><td></td></tr><tr><td><strong class=\"source-bold\">ブルガリア</strong></td><td><strong class=\"source-bold\">黒海</strong></td><td><strong class=\"source-bold\">ジョージア（グルジア）</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">トルコ</strong></td><td></td></tr></tbody></table></div>\n<p>では、そもそもなんでロシアがウクライナへの進出を狙うんだろうか。現在のウクライナ地域は、中世には<strong class=\"source-bold\">キエフ公国</strong>があったけど、13世紀の<strong class=\"source-bold\">モンゴルの遠征でキエフ公国が崩壊</strong>すると、かわって<strong class=\"source-bold\">モスクワ大公国が台頭</strong>し、それが<strong class=\"source-bold\">ロシア帝国に発展</strong>したよね。だから、キエフ（つまりウクライナ）のほうが長い歴史を持ち、宗教的（東方正教会のなかでの地位）にも権威があるともいえるんだ。また、領土面では18世紀までは、ほぼ<strong class=\"source-bold\">ドニエプル川を境に西は「ポーランド王国」、東は「ロシア帝国」</strong>の領域に二分されていて、これが2014年ころまでのウクライナで西部が「<strong class=\"source-bold\">親西欧派</strong>」、東部が「<strong class=\"source-bold\">親ロシア派</strong>」に分かれていた理由だよ。地図を見るとわかるけ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "482": "<h2>482</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>ど、ウクライナ東部を<ruby>併合<rt>へいごう</rt></ruby>すれば、<strong class=\"source-bold\">ロシアからクリミア半島への陸路が確保できる</strong>からね。そして、ウクライナはロシア寄りの政権だったんだ。</p>\n<p>ただ、プーチンがクリミア半島を併合し、ウクライナ東部にも派兵したことで、かえって<strong class=\"source-bold\">ウクライナ国内で反ロシアの世論が高まってしまった</strong>。2019年には<strong class=\"source-bold\">親西欧派</strong>の<strong class=\"source-bold\">ゼレンスキー</strong>がウクライナ大統領になって、<strong class=\"source-bold\">EUへの加盟を模索するなど西欧に接近</strong>したから、反発したロシアの<strong class=\"source-bold\">プーチン</strong>はウクライナ東部の親ロシア派地域の保護を口実に、2022年には全面的に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウクライナに<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>したんだ。これに対し、<strong class=\"source-bold\">アメリカやEU、日本などがウクライナへの経済的・軍事的支援やロシアへの経済制裁</strong>を強めたけど、<strong class=\"source-bold\">中国はロシアとの関係を強化</strong>するなど、世界の分断が進んだよ。また、ロシアの侵攻開始後、<strong class=\"source-bold\">首都キエフは</strong>「キーウ」、ドニエプル川は「<strong class=\"source-bold\">ドニプロ川</strong>」など、<strong class=\"source-bold\">地名がウクライナ語で呼ばれるようになった</strong>んだ。さらに、ロシアがウクライナに軍事侵攻したことで、これまで中立の立場をとっていた<strong class=\"source-bold\">北欧のフィンランドとスウェーデン</strong>がロシアの軍事侵攻を警戒して<strong class=\"source-bold\"><ruby>NATO<rt>ナトー</rt></ruby>への加盟</strong>に傾くなど（フィンランドは2023年4月に正式加盟、スウェーデンの加盟も実現する見込み［2023年9月現在］）、ヨーロッパの国際関係に変化が生じているね。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈ヨーロッパの統合とEUの成立〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ECの<ruby>市場<rt>しじょう</rt></ruby>統合が進み、今度は政治統合を目指してEUが成立！</strong></span></h4>\n<p>1973年以降、どんどん加盟国が増えたEC（表<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.410</strong></span>）では1987年<strong class=\"source-bold\">単一欧州<ruby>議定書<rt>ぎていしょ</rt></ruby></strong>で「1992年までに<strong class=\"source-bold\">ECが完全市場統合を目指す</strong>！」って合意し、市場統合のあとのヨーロッパの統合についての話し合いが始まった。そして、<strong class=\"source-bold\"><ruby>冷戦<rt>れいせん</rt></ruby>の終結や東西ドイツの統一</strong>を受けて、「市場統合のあとは<strong class=\"source-bold\">政治統合と通貨統合</strong>だ」という目標を決めると、1992年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マーストリヒト条約</strong></span>が結ばれたんだ。こうして翌年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ連合</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EU</strong></span>】</strong>が発足し、<strong class=\"source-bold\">共通市民権</strong>を導入したり、<strong class=\"source-bold\">欧州議会の権限を強化</strong>したりと、ヨーロッパの統合を新たな段階に進めたよ。この時に中心となったのは<strong class=\"source-bold\">フランス</strong>のミッテラン大統領と<strong class=\"source-bold\">ドイツ</strong>のコール首相だ。EUのなかって、<strong class=\"source-bold\">仏独が組んで主導権を握り</strong>、イギリスは一歩引いている。だから、通貨統合の時にもイギリスは「通貨を発行するのは独立国の主権だから」と言って、参加しないことになった。</p>\n<blockquote><p>これからは、EUの権限と各国の主権の関係をどうするかが問題だ！ 通貨<strong class=\"source-bold\">発行権</strong>って、主権の1つだもんね</p></blockquote>\n<p>そして、1999年には<strong class=\"source-bold\">共通貨幣</strong>として「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーロ</strong></span>」が導入され、2002年からは各国で共通の紙幣や硬貨の使用が始まったよ。ただ、<strong class=\"source-bold\">イギリス、デンマーク、スウェーデンなどは、ユーロを導入しなかった</strong>んだ。</p>",
  "483": "<h2>483</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦終結後の欧米諸国</u></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ どんどん増える加盟国。EUはいったいどこに向かうんだろう？</strong></span></h4>\n<p>冷戦が終わったことで<strong class=\"source-bold\">ヨーロッパの東西分断がなくなり</strong>、EUにも新たな役割ができたことは確かだよ。1995年に<strong class=\"source-bold\">オーストリア、スウェーデン、フィンランド</strong>が加盟したことで、かつての共産圏を除いたほとんどのヨーロッパ諸国がEUに入り、さらに、21世紀に入ってその勢いは旧共産圏にも広がったんだ。</p>\n<p>2004年には、<strong class=\"source-bold\">東欧諸国を中心</strong>に10カ国（<strong class=\"source-bold\">ポーランド・チェコ・スロヴァキア・ハンガリー・バルト3国・マルタ・キプロス・スロヴェニア</strong>）が一気に加盟した。さらに2007年にはブルガリア、ルーマニア、2013年にはクロアティアの加盟も実現し、もはやヨーロッパのなかでEUに加盟していない国は、かなりの少数派になったよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 共通通貨ユーロの危機、そして…イギリスのEU離脱。EUはどうなるのか？</strong></span></h4>\n<p>2008年の<strong class=\"source-bold\">世界金融危機の影響</strong>で、2009年に<strong class=\"source-bold\">ギリシアで財政危機</strong>が起きた。この影響で<strong class=\"source-bold\">ユーロ圏では信用不安が起き</strong>てEU全体の経済が大きなダメージを受けたから、下手をすると共通通貨「ユーロ」が<ruby>崩壊<rt>ほうかい</rt></ruby>してしまう。この時、<strong class=\"source-bold\">ドイツとフランスを中心</strong>にギリシアを支援して、ギリギリのところでなんとか食い止めたけど、金融危機はなかなか収まらず、<strong class=\"source-bold\">EU各国に財政危機が飛び火</strong>、ついにはEUのなかでは大国の<strong class=\"source-bold\">スペイン、イタリア</strong>などにまで、財政不安が拡大したんだ（<strong class=\"source-bold\">ユーロ危機</strong>）。これが原因で「EUよりも自分の国が大事」という世論が広がった国もある。</p>\n<p>それでもEUは統合をさらに深化させていったんだ。2009年には<strong class=\"source-bold\">リスボン条約</strong>が発効して<strong class=\"source-bold\">EU大統領（正式にはヨーロッパ理事会の常任委員長）が新設</strong>されるなど、政治統合がさらに進んだよ。ただ、統合を進めたことで「EU」と「<strong class=\"source-bold\">自国の主権」との関係が問題になった</strong>国もあった。それがイギリスだよ。</p>\n<p><strong class=\"source-bold\">イギリスでは移民に対する反感が強まっていた</strong>。これは、国境の自由往来を決めた<strong class=\"source-bold\">シェンゲン協定</strong>が正式にEUの法律になったこと（アムステルダム条約［1997］）が背景だよ。問題となっていたのは、1つは新たにEUに加盟した<strong class=\"source-bold\">東欧諸国（特にポーランドなど）から賃金の高いイギリスに流入した多くの移民労働者</strong>、もう1つはシリア内戦などから逃れてきた<strong class=\"source-bold\">ムスリム系の難民</strong>だ。特に、イギリス人の低賃金労働者は「オレたちの仕事が取られるだろ！」と東欧系の移民に反発し、加えてムスリム過激派のテロが起きていたことも移民への反感をさらに高めた。こうしたことが、「EUにいるとイギリスが損をするから、離脱しろ！」って世論につながったんだ。</p>\n<blockquote><p>もともとヨーロッパ統合から距離をとってはいたけど、大国イギリスの離脱はEUにとってダメージだよね</p></blockquote>\n<p>2016年、イギリスではキャメロン首相が<strong class=\"source-bold\">EU離脱の是非を問う国民投票</strong>をやったんだけど、なんと<strong class=\"source-bold\">離脱賛成派が勝利</strong>した。でも、<strong class=\"source-bold\">EU離脱問題（ブレグジット）</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "484": "<h2>484</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>で国論が二分されて、続く保守党のメイ首相は離脱を進められずに辞任したんだけど、2020年に保守党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>首相が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリスのEU離脱</strong></span>を実現したんだ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈西ヨーロッパ各国の国内問題〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ イギリス――ブレアがイラク戦争に出兵！金融危機後は保守党政権へ</strong></span></h4>\n<p>サッチャーがあまりにも存在感がありすぎて、続く保守党の首相<strong class=\"source-bold\">メージャー</strong>はさんざん「指導力不足だ」と言われ続け、1997年の総選挙では18年ぶりに<strong class=\"source-bold\">労働党</strong>が勝ったんだ。こうして首相になった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレア</strong></span>は、労働党の政策を<strong class=\"source-bold\">保守党に近い現実路線（右派寄り）に転換</strong>して、「企業の国有化」とか言わないことにした。そして、<strong class=\"source-bold\">北アイルランドの和平合意</strong>を成立させてアイルランド問題を解決に導き、さらに2007年には北アイルランド自治政府もできたよ。一方で、2003年には議会を説得して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラク戦争</strong></span>に出兵したけど、その後の<strong class=\"source-bold\">イラク情勢の混迷で批判が高まり辞任</strong>したんだ。</p>\n<blockquote><p>ブレアの政策転換で、イギリスの二大政党の違いがわかりにくくなり、しまいにはイギリスも連立政権に……</p></blockquote>\n<p>あとを受けた労働党の<strong class=\"source-bold\">ブラウン</strong>首相は、最初はまあまあ支持率も高かったんだけど、<strong class=\"source-bold\">世界金融危機に対応できず</strong>に総選挙で大敗。かわって<strong class=\"source-bold\">保守党のキャメロン</strong>が、史上最年少で首相になった。ただ、従来の保守党の政策（サッチャリズム）とは距離を置いて左派寄りになったから、“本当に”保守的な自由民主党が議席を増やして、結局<strong class=\"source-bold\">イギリスは戦後初の連立政権</strong>（保守党と自由民主党）になったんだ。しかも、キャメロンは<strong class=\"source-bold\">スコットランドの独立問題に関する国民投票</strong>をやってしまった！。結果は否決されたけど、政治が混乱したんだ。さらに、<strong class=\"source-bold\">EU離脱問題でも国民投票</strong>をやってしまい、こちらは離脱派が勝利したからイギリスの国論が二分されたんだ。その後、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EU離脱</strong></span>を実現した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>首相は指導力が評価されてはいたけど、新型コロナ感染症期間のスキャンダルなどで辞任し、2022年には<strong class=\"source-bold\">スナク</strong>が首相に就任した。彼は、<strong class=\"source-bold\">イギリス初の非白人（インド系）首相</strong>だよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ フランス――<ruby>核<rt>かく</rt></ruby>実験を強行したシラク、親米のサルコジ</strong></span></h4>\n<p>社会党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミッテラン</strong></span>のあと、1995年に右派の<strong class=\"source-bold\">シラク</strong>が大統領になったんだけど、就任してすぐに<strong class=\"source-bold\">ムルロア<ruby>環礁<rt>かんしょう</rt></ruby>での地下核実験を強行</strong>したことから、世界中の批判を浴びた。これね、<strong class=\"source-bold\"><ruby>包括<rt>ほうかつ</rt></ruby>的核実験禁止条約【CTBT】の調印直前</strong>だったことも、非難の対象になったんだよ。その後、<strong class=\"source-bold\">イラク戦争では米英主導の出兵に反対</strong>して、外交ではフランスの存在感を示した。一方、国内では経済が低迷して若者の失業率が上がり、デモが頻発するなど、動揺が続いたんだ。</p>\n<p>そして、2007年には経済再建を訴えた<strong class=\"source-bold\">サルコジ</strong>が大統領となり、フランスとして</p>",
  "485": "<h2>485</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦終結後の欧米諸国</u></p></blockquote>\n<p>は異例の<strong class=\"source-bold\">親米路線</strong>をとって<strong class=\"source-bold\"><ruby>NATO<rt>ナトー</rt></ruby>軍事機構にも復帰</strong>したよ。そして、<strong class=\"source-bold\">世界金融危機</strong>や、その後の<strong class=\"source-bold\">欧州の経済危機</strong>に対して<strong class=\"source-bold\">ドイツと協調してEUをリード</strong>したものの、国内での緊縮財政や増税によって支持率が下がり、2012年の大統領選挙では社会党の<strong class=\"source-bold\">オランド</strong>に敗北しちゃった。オランドはミッテラン以来の<strong class=\"source-bold\">社会党政権</strong>だったけど、高い失業率だったから支持が伸びず、一方で、イギリスのEU離脱問題の影響を受けて、フランスでも<strong class=\"source-bold\">EU離脱を主張する<ruby>極右<rt>きょくう</rt></ruby>政党の勢力が拡大</strong>したんだ！。でも、フランス人はバランス感覚があるんだろうね。極右に政権を取られちゃマズいと思った人が多かったんだろう、2017年には<strong class=\"source-bold\">中道路線</strong>をとる<strong class=\"source-bold\">マクロン</strong>が大統領になったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ドイツ――統一後の<ruby>不況<rt>ふきょう</rt></ruby>。そして、初の女性首相メルケルが登場</strong></span></h4>\n<p><strong class=\"source-bold\">西ドイツ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コール</strong></span>政権（<strong class=\"source-bold\">キリスト教民主同盟</strong>）が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東西ドイツ統一</strong></span>を成し遂げたものの、旧東ドイツの経済があまりにもひどすぎて、旧西ドイツには東の再建のための特別税がかけられるなど、負担が大きかった。さらに<strong class=\"source-bold\">EUの成立</strong>などを背景に、外国人労働者が給料の高いドイツに流入し、<strong class=\"source-bold\">ドイツ人の失業者が増えた</strong>んだ。</p>\n<p>こうした不満から「<strong class=\"source-bold\">ネオ＝ナチ</strong>」などの極右勢力の運動が活発化するなど社会不安が広がり、1998年の総選挙では<strong class=\"source-bold\">社会民主党</strong>が勝利して、<strong class=\"source-bold\">シュレーダー</strong>が首相になった。シュレーダー政権は、環境政党「<strong class=\"source-bold\">緑の党</strong>」との連立政権だったため、<strong class=\"source-bold\">原子力発電所の全廃を決定</strong>するなど、ほかの先進国とは少し違った政策を打ち出した。また、<strong class=\"source-bold\">イラク戦争では米英の出兵にフランスとともに反対</strong>するなど、独仏の連携を続けたよ。</p>\n<blockquote><p>環境政党「緑の党」が一定の力を持ってるから、ドイツの政権は、環境問題に敏感なんだ！</p></blockquote>\n<p>その後、2005年から<strong class=\"source-bold\">キリスト教民主同盟</strong>の<strong class=\"source-bold\">メルケル</strong>が首相を務めたよ。メルケルは、<strong class=\"source-bold\">ドイツ初の女性首相</strong>で、<strong class=\"source-bold\">初の旧東ドイツ出身</strong>の首相だ。当初は、シュレーダー政権の<ruby>原発<rt>げんぱつ</rt></ruby>廃止の方針をやめて「<strong class=\"source-bold\">原発推進」に転換</strong>するなど、右寄りの政策をとったんだけど、2011年には日本の福島第一原発事故を受けて、いち早く「<strong class=\"source-bold\">脱原発」を発表</strong>した。また長期にわたって<strong class=\"source-bold\">EUを主導</strong>してユーロ危機などに対処し、<strong class=\"source-bold\">移民や難民の問題でも人権優先の姿勢を貫いた</strong>ほか、新型コロナ感染症対策でも指導力を発揮した。彼女が引退したあとに首相となった社会民主党の<strong class=\"source-bold\">ショルツ</strong>は、ロシアのウクライナ<ruby>侵攻<rt>しんこう</rt></ruby>に対して厳しく対応し、<strong class=\"source-bold\">ウクライナへの武器供与</strong>に踏み切ったほか、2023年には、ついに<strong class=\"source-bold\">国内での原発ゼロを実現</strong>したよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "486": "<h2>486</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-background=\"white\" data-source-border=\"red\" data-source-border-pattern=\"diagonal-lines\" style=\"border:1px solid #e52715;background:repeating-linear-gradient(135deg,#fff 0 4px,#fbe1e1 4px 5px);padding:0 0.2em\"><strong class=\"source-bold\">現代の諸問題</strong></span></h3>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈冷戦終結後の経済問題〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ タイ＝バーツの暴落から、アジア経済を揺るがしたアジア通貨危機！</strong></span></h4>\n<p>ここからは<strong class=\"source-bold\">経済問題</strong>だよ。まずは1997年に起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アジア通貨危機</strong></span>だ。1980年代には、韓国、タイ、インドネシアなど<strong class=\"source-bold\">アジアの新興国が急激に経済発展</strong>したんだけど、この発展は<strong class=\"source-bold\">先進国からの投資</strong>による<strong class=\"source-bold\">輸出産業の成長</strong>で実現したものだから、国内の経済全体が発展したわけじゃない。そして、1990年代前半に<strong class=\"source-bold\">日本がバブル経済の崩壊</strong>で大<ruby>不況<rt>ふきょう</rt></ruby>になると一気に円安が進み、かわって<strong class=\"source-bold\">新興国の通貨がどんどん上がった</strong>。これは、世界の投資家が「日本の景気が悪すぎる」って思って円を売ったことで、相対的に新興国の通貨が上がっただけだから、経済の規模とは釣り合わないくらいの過大評価だったんだ。</p>\n<p>ただ、<strong class=\"source-bold\">通貨が高くなると輸出が不利</strong>になり、<strong class=\"source-bold\">輸出産業に頼る新興国は一気に不況</strong>になった。でも通貨は上がっているから、これに目をつけた国際的な<strong class=\"source-bold\">ヘッジ・ファンド</strong>（投資<ruby>信託<rt>しんたく</rt></ruby>。巨額のお金を動かすだけで<ruby>儲<rt>もう</rt></ruby>けようとしている巨大投資家だよ）が、「新興国の通貨を買いまくって通貨高にして、上がったところで売ればボロ儲けだ！」とたくらんだ。標的になったのが<strong class=\"source-bold\">タイの通貨バーツ</strong>だよ。</p>\n<p>こうして起きた<strong class=\"source-bold\">タイ＝バーツの暴落</strong>は韓国やインドネシアなどにも波及し、<strong class=\"source-bold\">韓国では<ruby>国債<rt>こくさい</rt></ruby>が返せなくなる危機（デフォルト）に陥る</strong>など、アジア全体に不況が拡大し、<strong class=\"source-bold\">タイ、韓国、インドネシアは国際通貨基金【IMF】の融資を受け</strong>て、なんとか助かったんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アジア通貨危機</strong></span>だよ。この影響は、特に経済基盤の弱い<strong class=\"source-bold\">ロシアや中南米諸国にも波及</strong>して、ロシアでも通貨の引き下げに追い込まれた。また、この影響で、<strong class=\"source-bold\">インドネシア</strong>では国民の不満が爆発し、<ruby>独<rt>どく</rt></ruby><ruby>裁<rt>さい</rt></ruby>政権を維持していた<strong class=\"source-bold\">スハルトが退陣</strong>したよね。</p>\n<blockquote><p>日本経済は、バブル崩壊からやっと立ち直れるかと思ったら、アジア通貨危機で、またまた打撃を受けたんだよ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「神話」はニセモノだ！ 「家神話」の崩壊から、世界経済危機が起こる！</strong></span></h4>\n<p>続いて、2008年に起きた<strong class=\"source-bold\">リーマン＝ショック</strong>による<strong class=\"source-bold\">世界金融危機</strong>だよ。アメリカでは<strong class=\"source-bold\">住宅価格の高騰</strong>で「住宅価格は下がらない」という「家神話」が生まれていて、<ruby>貧困<rt>ひんこん</rt></ruby>層がとんでもない高金利の住宅ローン（<strong class=\"source-bold\">サブプライム・ローン</strong>）を組んで家を買っていたんだけど、<strong class=\"source-bold\">住宅価格が急落して返済不能となった人が急増</strong>したんだ。こうして2007年ごろから、アメリカでは回収できない住宅ローン（不良<ruby>債権<rt>さいけん</rt></ruby>）を抱えた<strong class=\"source-bold\">金融機関の<ruby>破綻<rt>はたん</rt></ruby></strong>が始まり、ついに2008年、アメリカの<strong class=\"source-bold\">大手証券会社のリーマン＝ブラザーズが経営破綻</strong>した。なんと<ruby>負債<rt>ふさい</rt></ruby>総額は約60兆円！ これをきっかけ</p>",
  "487": "<h2>487</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">現代の諸問題</u></p></blockquote>\n<p>にして<strong class=\"source-bold\">各国の株価が大暴落</strong>し、世界全体に不況が拡大、世界的な金融危機が起きた。この不況は<strong class=\"source-bold\">1929年の世界<ruby>恐慌<rt>きょうこう</rt></ruby>にも匹敵するものともいわれ</strong>、経済の落ち込みとともに、<strong class=\"source-bold\">各国の財政危機</strong>を招いたんだ。</p>\n<p>この影響で<strong class=\"source-bold\">各国では政権交代が相次ぎ</strong>、アメリカでは共和党にかわって民主党オバマ政権が、イギリスでは保守党が政権を<ruby>奪還<rt>だっかん</rt></ruby>してキャメロン政権が誕生し、日本でも、自民党が総選挙で大敗して、民主党の<ruby>鳩山<rt>はとやま</rt></ruby>政権が誕生した。さらに、この世界的な経済危機は、もはや<strong class=\"source-bold\">先進国（G7）だけでどうこうできる状況を超えていた</strong>から、新興国も含めた<strong class=\"source-bold\">G20</strong>という枠組みが、国際的な地位を上げることになった。</p>\n<p>G20とは、これまでの<strong class=\"source-bold\">G7（米・英・日・仏・独・伊・カナダ）</strong>に、<strong class=\"source-bold\"><ruby>BRICS<rt>ブリックス</rt></ruby>（ブラジル・ロシア・インド・中国・南アフリカ）</strong>や、韓国、サウジアラビア、インドネシア、トルコなどを加えたもので、2008年に開かれた第1回首脳会談では、金融危機への対応で協調することを確認したんだ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈反核運動と核軍縮問題〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 第二次世界大戦が終わると、反<ruby>核<rt>かく</rt></ruby>運動が始まった！</strong></span></h4>\n<p>核<ruby>軍縮<rt>ぐんしゅく</rt></ruby>問題の前に、<strong class=\"source-bold\">第二次世界大戦後の反核運動</strong>について見ておこう。米ソの核開発競争に対して、1950年の<strong class=\"source-bold\">世界平和<ruby>擁護<rt>ようご</rt></ruby>大会</strong>で<strong class=\"source-bold\">核兵器禁止の署名運動</strong>をおこなうことが決まり、世界から5億を超える署名が集まった（<strong class=\"source-bold\">ストックホルム＝アピール</strong>）。そして、核兵器の恐ろしさを世界に痛感させたのが、<strong class=\"source-bold\">第五<ruby>福竜丸<rt>ふくりゅうまる</rt></ruby>事件</strong>だ。日本のマグロ漁船第五福竜丸が南太平洋で操業している最中に、アメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビキニ<ruby>環礁水爆<rt>かんしょうすいばく</rt></ruby>実験</strong></span>で降った<strong class=\"source-bold\">高濃度の放射性物質</strong>（「<strong class=\"source-bold\">死の灰</strong>」）を浴びて<ruby>被曝<rt>ひばく</rt></ruby>した。乗組員はあまりに強い放射線で皮膚がただれ、髪が抜ける、いわゆる「<ruby>原爆<rt>げんばく</rt></ruby><ruby>症<rt>しょう</rt></ruby>」の症状になったんだ。この事件をきっかけに<strong class=\"source-bold\">東京都<ruby>杉並<rt>すぎなみ</rt></ruby>区の主婦たちから始まった</strong>「核兵器をなくせ！」という運動は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>原水爆<rt>げんすいばく</rt></ruby>禁止運動</strong></span>となり、世界に拡大したよ。さらに、この運動は科学者たちにも影響を与え、<strong class=\"source-bold\">哲学者</strong>の<strong class=\"source-bold\">バートランド＝ラッセル</strong>と<strong class=\"source-bold\">物理学者</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アインシュタイン</strong></span>は「核戦争は人類絶滅の危機だ！」と警告し（<strong class=\"source-bold\">ラッセル・アインシュタイン宣言</strong>）、1955年には人類史上最初の被爆地広島で、第1回<strong class=\"source-bold\">原水爆禁止世界大会</strong>が開かれた。</p>\n<blockquote><p>ビキニ環礁の水爆実験では直径2キロのクレーターができた！。こんなんじゃ、人類滅亡だよ……</p></blockquote>\n<p>その後も反核運動は続き、<strong class=\"source-bold\">西ドイツの科学者たち</strong>は「何があっても<strong class=\"source-bold\">西ドイツは核武装すべきではない</strong>」とする<strong class=\"source-bold\">ゲッティンゲン宣言</strong>を発表し、さらに1957年には、<strong class=\"source-bold\">ラッセルとアインシュタインを中心</strong>に、<strong class=\"source-bold\">カナダ</strong>のパグウォッシュで「科学と国際問題に関する会議」、通称<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パグウォッシュ会議</strong></span>が開かれ、第五福竜丸事件後の放射線調査をふまえて、<strong class=\"source-bold\">核実験の人体に与える影響を警告</strong>したんだ。以後、毎年場所を変え</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "488": "<h2>488</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>て開かれ、<strong class=\"source-bold\">科学者による<ruby>核<rt>かく</rt></ruby>兵器禁止運動</strong>をまとめる組織になったよ。</p>\n<p>ちなみに、ビキニ<ruby>環礁<rt>かんしょう</rt></ruby>の核実験のために強制的に移住させられた島民たちは、放射能汚染のために、半世紀以上経った今も島に帰ることができない。これが「核」の恐ろしさだよね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>冷戦<rt>れいせん</rt></ruby>終結後には核<ruby>軍縮<rt>ぐんしゅく</rt></ruby>が進むと思いきや、米ロ交渉はなかなか進まず</strong></span></h4>\n<p>冷戦期の核軍縮交渉はすでに見たので、ここでは冷戦終結後の核軍縮を見ていくよ。まずは<strong class=\"source-bold\">米ソ（米ロ）間の交渉</strong>だ。1991年、<strong class=\"source-bold\">アメリカ</strong>大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">父</strong></span>）とソ連の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフ</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次戦略兵器削減条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>START<rt>スタート</rt></ruby>Ⅰ</strong></span>】</strong>に調印し、戦略核兵器を核<ruby>弾頭<rt>だんとう</rt></ruby>（核爆弾のこと）6000発、運搬手段（こっちはミサイル）1600基以下に削減することを約束した。ただ、この年の年末に<strong class=\"source-bold\">ソ連が<ruby>崩壊<rt>ほうかい</rt></ruby></strong>したので、これ以後の交渉は、<strong class=\"source-bold\">アメリカとロシア</strong>によっておこなわれることになったんだ。</p>\n<p>1993年にはアメリカ大統領<strong class=\"source-bold\">ブッシュ（父）</strong>とロシア大統領<strong class=\"source-bold\">エリツィン</strong>が<strong class=\"source-bold\">第2次戦略兵器削減条約【STARTⅡ】</strong>に調印して、STARTⅠよりも大幅に核兵器を削減することになったんだけど、<strong class=\"source-bold\">実際の削減は進まず</strong>、期限の2007年までに実行できなかったため、<strong class=\"source-bold\">第3次戦略兵器削減条約【STARTⅢ】の交渉は打ち切り</strong>になっちゃった。そして、オバマ大統領の「<strong class=\"source-bold\">プラハ宣言</strong>」を受けて交渉が進み、2010年には<strong class=\"source-bold\">アメリカ</strong>の<strong class=\"source-bold\">オバマ</strong>大統領と<strong class=\"source-bold\">ロシア</strong>の<strong class=\"source-bold\">メドヴェージェフ</strong>大統領との間で、新たな核軍縮の枠組みを決めると<strong class=\"source-bold\">第4次戦略兵器削減条約【新START】</strong>が結ばれた。両国は「国ではなくテロ組織が核兵器を持つ危険性」から、合意に至ったんだね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「あらゆる核実験禁止！」のはずが発効しないCTBT。そして、核はさらに拡散！</strong></span></h4>\n<p>1996年、<strong class=\"source-bold\">国連総会</strong>で158カ国の賛成で<ruby>採択<rt>さいたく</rt></ruby>された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>包括<rt>ほうかつ</rt></ruby>的核実験禁止条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">CTBT</strong></span>】</strong>は、<strong class=\"source-bold\">あらゆる核兵器の“爆発”実験を禁止</strong>しているんだけど、この条約は問題が多いんだ。まず条約の発効には、<strong class=\"source-bold\">核保有国と指定44カ国の<ruby>批准<rt>ひじゅん</rt></ruby>が必要</strong>とされたんだけど、<strong class=\"source-bold\">インドなどの反対で発効できていない</strong>。それから、禁止されたのは「爆発」実験だから、アメリカやロシアなど、これまでの核実験のデータがたくさんある国は、<strong class=\"source-bold\">爆発寸前で核反応を止めて</strong>、あとはコンピューターでシミュレーションする「<strong class=\"source-bold\"><ruby>臨界前<rt>りんかいまえ</rt></ruby>実験</strong>」をやっているんだよ。<strong class=\"source-bold\">フランス</strong>や<strong class=\"source-bold\">中国</strong>は「米ロはこれまで何度も実験をしてきたじゃないか！」と反発し、<strong class=\"source-bold\">国連総会でCTBTが採択される直前</strong>の1995年に、駆け込みで<strong class=\"source-bold\">核実験</strong>をおこなったんだ。</p>\n<blockquote><p>イスラエルの核保有を一緒に議論しないと、イランの核問題は解決しないだろうなぁ……</p></blockquote>\n<p>また、<strong class=\"source-bold\">核兵器の拡散</strong>も問題だよね。インドの核保有に反発した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>が1998年に<strong class=\"source-bold\">核保有国になった</strong>話はすでにしたけど、それ以外にも</p>",
  "489": "<h2>489</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">現代の諸問題</u></p></blockquote>\n<p>核開発が問題になっている国があるよ。まずは<strong class=\"source-bold\">イラン</strong>だ。</p>\n<p><strong class=\"source-bold\">イランの核開発</strong>は国内での石油<ruby>需要<rt>じゅよう</rt></ruby>の増大から、輸出用の石油を確保するために<strong class=\"source-bold\">原子力発電を開発</strong>していたんだけど、2001年の同時多発テロ事件【9.11事件】後にアメリカに「<strong class=\"source-bold\">悪の<ruby>枢軸<rt>すうじく</rt></ruby></strong>」と名指しされ、しかもブッシュ（子）大統領が「<strong class=\"source-bold\">平和利用も含めてイランの核開発を認めない</strong>」と言ったので、アメリカとの関係がさらに悪化した。2005年に強硬派の<strong class=\"source-bold\">アフマディネジャド</strong>大統領が就任すると、「イスラエルも核兵器を持っている（これは世界では公然の秘密ね）から、イスラーム国家も核を持つべきである」という論理で、<strong class=\"source-bold\">反米・反イスラエル外交を強めた</strong>んだ。こうして欧米諸国との対立が深まり、国連<ruby>安保理<rt>あんぽり</rt></ruby>でもイランに核開発の中止を求める決議が採択されたけど、イランは激しく抵抗した。その後、2013年にはイランで<strong class=\"source-bold\">ロウハニ</strong>大統領が就任して<strong class=\"source-bold\">欧米とも対話していくという路線</strong>を打ち出し、2015年には<strong class=\"source-bold\">イランが核開発を大幅に制限する合意が実現</strong>したよ。その後、<strong class=\"source-bold\">アメリカのトランプ大統領がこの合意を一方的に破棄</strong>したから、関係は再び悪化したんだ。</p>\n<p>それから<strong class=\"source-bold\">北朝鮮の核問題</strong>も深刻だね。イランと同じように「<strong class=\"source-bold\">悪の枢軸</strong>」と名指しされた北朝鮮は、「日米韓が北朝鮮を包囲している！」あるいは「在韓米軍が核兵器を持っている！」と<strong class=\"source-bold\">アメリカに反発して核開発を進めた</strong>んだ。これに対し2003年以降、<strong class=\"source-bold\">中国を議長国</strong>として<strong class=\"source-bold\">アメリカ・日本・ロシア・韓国・北朝鮮</strong>で<strong class=\"source-bold\">六カ国協議</strong>が始まった。でも、<strong class=\"source-bold\">北朝鮮のミサイル実験</strong>などでたびたび中断したため交渉は進まず、2006年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北朝鮮</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">核保有国</strong></span>になってしまい、その後も核実験やミサイル実験を繰り返している。核の拡散は深刻な問題だ。</p>\n<p>2017年には国連の会議で<strong class=\"source-bold\">核兵器禁止条約</strong>も採択されたけど、<strong class=\"source-bold\">全核保有国が不参加</strong>で、またカナダ、ドイツ、韓国など、<strong class=\"source-bold\">アメリカの「核の傘」の下にある国も不参加</strong>だ。唯一の戦争被爆国の<strong class=\"source-bold\">日本も不参加</strong>なのは、少し考えさせられるね。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈米中新冷戦〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>習近平<rt>しゅうきんぺい</rt></ruby>体制の中国が大国への野心を強め、アメリカとの対立が激化！</strong></span></h4>\n<p>2010年にGDP（国内総生産）で世界2位となった<strong class=\"source-bold\">中国</strong>では、2012年に総書記となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">習近平</strong></span>が、国内では自分自身への権力集中をはかって<strong class=\"source-bold\">強権的な政治体制</strong>を実現したんだ。<strong class=\"source-bold\"><ruby>新疆<rt>しんきょう</rt></ruby>ウイグル自治区</strong>に対しての人権抑圧を強化したり、<strong class=\"source-bold\"><ruby>香港<rt>ホンコン</rt></ruby>の民主化運動</strong>も厳しく抑え込んで、<strong class=\"source-bold\">国家安全維持法</strong>を制定して共産党への批判も違法としたよ。これで事実上、<strong class=\"source-bold\">一国二制度は崩壊</strong>したんだ。国際的には批判されているけど気に留める様子もなく、かえって激しく反発しているよね。</p>\n<p>また急激な<strong class=\"source-bold\">軍事力強化</strong>を進め、対外的には<strong class=\"source-bold\">東シナ海や南シナ海において強引な海洋進出</strong>をはかり、日本の<strong class=\"source-bold\"><ruby>尖閣<rt>せんかく</rt></ruby>諸島</strong>への圧力を強めているほか、<strong class=\"source-bold\">南シナ海のほぼ全域の領有権を主張</strong>して、フィリピン、マレーシア、ベトナム、インドネシアなどと対立している。また、台湾を<ruby>併合<rt>へいごう</rt></ruby>（「統一」）するという野心をむき出しにして、年々<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">台湾</strong></span><strong class=\"source-bold\">への圧力を強め</strong>、盛んに軍事演習をおこなうなど緊張が高まっている。対する<strong class=\"source-bold\">アメリカ</strong>は下院議長が台湾を訪問するなど、<strong class=\"source-bold\">台湾との関係を強めようとしている</strong>ね。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "490": "<h2>490</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>そして、経済的には<strong class=\"source-bold\">アジア・ヨーロッパ・アフリカにまたがる広大な経済圏構想</strong>（「<strong class=\"source-bold\"><ruby>一帯一路<rt>いったいいちろ</rt></ruby></strong>」）を打ち出し、<strong class=\"source-bold\">巨額の援助によってアジア・アフリカの新興国への影響力を強めている</strong>。こうした動きは、世界1位の経済力・軍事力を保持する<strong class=\"source-bold\">アメリカに対抗</strong>するもので、両国間では貿易で保護関税を掛けあったり、知的財産権、新技術において<ruby>覇権<rt>はけん</rt></ruby>を争うなど、多くの分野で対立が深まっている。こうした状況を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米中新冷戦</strong></span>と呼ぶこともあるよ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈環境問題・SDGs〉</strong></span></h3>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ 京都<ruby>議定書<rt>ぎていしょ</rt></ruby>、パリ協定…温暖化防止のため、世界は「脱炭素社会」を目指す！</strong></span></h4>\n<p>環境問題をテーマに開かれた最初の国際会議は、1972年に<strong class=\"source-bold\">スウェーデンのストックホルム</strong>で開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連人間環境会議</strong></span>だ。この会議では「かけがえのない地球（Only One Earth）」をスローガンに、「<strong class=\"source-bold\">人間環境宣言</strong>」が<ruby>採択<rt>さいたく</rt></ruby>されて、<strong class=\"source-bold\">国連環境計画【UNEP】が創設された</strong>。そして1980年代に入ると<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">地球温暖化</strong></span>の危険性が明らかになってきた。こうして1992年、<strong class=\"source-bold\">ブラジルのリオデジャネイロ</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">地球サミット</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">環境と開発に関する国連会議</strong></span>】</strong>が開かれ、自然と調和した経済開発の必要性を訴える「<strong class=\"source-bold\">リオ宣言</strong>」と、それを実現するための「<strong class=\"source-bold\">アジェンダ21計画</strong>」が採択され、さらに<strong class=\"source-bold\">気候変動枠組み条約</strong>を結んで<strong class=\"source-bold\">地球温暖化防止のための枠組み</strong>を定め、<strong class=\"source-bold\">気候変動枠組み条約締約国会議</strong>（通称：COP）が毎年開かれることになったんだ。</p>\n<p>これ以後、環境問題の中心は地球温暖化防止ということになり、1997年の<strong class=\"source-bold\">京都会議【COP3／第3回気候変動枠組み条約締約国会議】</strong>では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">京都議定書</strong></span>を採択して、温室効果ガス（おもにCO₂）の削減について、<strong class=\"source-bold\">先進国の削減目標</strong>を設定したんだ。でも、新興国に制限がなかったことから、反発した<strong class=\"source-bold\">アメリカは<ruby>批准<rt>ひじゅん</rt></ruby>を拒否</strong>した。当時、CO₂の排出量の上位2国はアメリカと中国だったから、その両国の協力がないと、世界全体での削減は難しいよね（<strong class=\"source-bold\">京都議定書は2004年にロシアが批准して、2005年に発効</strong>）。その後も先進国と新興国の対立が続いたんだけど、2015年の<strong class=\"source-bold\">パリ会議【COP21】</strong>では、京都議定書以来の新たな枠組みとなる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ協定</strong></span>が採択され、<strong class=\"source-bold\">途上国も含めたすべての国の温室効果ガス削減目標</strong>を定めることになったんだ（2016年に発効）。さらに2015年には国連サミットで「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SDGs</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">持続可能な開発目標</strong></span>】</strong>」（Sustainable Development Goals）が提唱され、<strong class=\"source-bold\">2030年までに持続可能な世界の実現を目指す国際目標</strong>を打ち出した。世界各国は<strong class=\"source-bold\">再生可能エネルギー</strong>（太陽光・風力など）などの開発によって<strong class=\"source-bold\">脱炭素社会</strong>（<strong class=\"source-bold\">CO₂の排出を実質ゼロにする社会）の実現を目指している</strong>けど、一方で<strong class=\"source-bold\">アメリカのトランプ政権がパリ協定から離脱</strong>したり、日本政府も経済発展を優先しがちだね。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ SDGsは環境だけじゃない！あらゆる差別をなくすことも国際目標だ！</strong></span></h4>\n<p>国連サミットで採択されたSDGsのなかには「<strong class=\"source-bold\">ジェンダー平等</strong>」や「<strong class=\"source-bold\">人や国の差別をなくす</strong>」といった目標もあるんだ。性差別については、すでに1979年に<strong class=\"source-bold\">女性差別撤廃条約</strong>が国連総会で採択され、日本でも1985年には<strong class=\"source-bold\">男女雇用機会均等法</strong>が制</p>",
  "491": "<h2>491</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">地域紛争・民族紛争の激化</u></p></blockquote>\n<p>定されたけど、2020年代における<strong class=\"source-bold\">ジェンダー＝ギャップ指数</strong>（男女間の格差を示す指数）において、<strong class=\"source-bold\">日本は先進国で最下位</strong>だ。特に政治・経済の分野での格差が深刻だね。また<strong class=\"source-bold\">LGBTQ</strong>の権利についても、<strong class=\"source-bold\">G7で同性婚を認めていないのは日本だけ</strong>だよ。あらゆる性への差別をなくすこと、社会のなかでの多様性を認めること、すべての人の人権を守るといったことも、環境問題と同じくらい重要だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-background=\"white\" data-source-border=\"red\" data-source-border-pattern=\"diagonal-lines\" style=\"border:1px solid #e52715;background:repeating-linear-gradient(135deg,#fff 0 4px,#fbe1e1 4px 5px);padding:0 0.2em\"><strong class=\"source-bold\">地域紛争・民族紛争の激化</strong></span></h3>\n<h4><strong class=\"source-bold\">〈ユーゴスラヴィア問題〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">オーストリア</strong></td><td><strong class=\"source-bold\">ハンガリー</strong></td><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td><strong class=\"source-bold\">イタリア</strong></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア</strong></span></span></td><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">アルバニア</strong></td><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td></td><td></td><td><strong class=\"source-bold\">トルコ</strong></td></tr></tbody></table></div>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">拡大図がこちら！</span></p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">スロヴェニア</strong></td><td><strong class=\"source-bold\">クロアティア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">カトリックが多数派</span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span></span></td><td><strong class=\"source-bold\">セルビア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ギリシア正教徒が多数派</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イスラーム教徒が多数派</span></td><td><strong class=\"source-bold\">モンテネグロ</strong></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">コソヴォ</strong></span></td></tr><tr><td></td><td><strong class=\"source-bold\">マケドニア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イスラーム教徒が多数派</span></td></tr><tr><td></td><td><strong class=\"source-bold\">アルバニア</strong></td><td></td></tr></tbody></table></div>\n<blockquote><p>ボスニア・ヘルツェゴヴィナが、民族対立の一番激しい地域だ！</p></blockquote>\n<blockquote><p>ユーゴスラヴィアには民族や宗教が入り乱れて、統一していたのが不思議なくらいだよ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ カリスマ指導者ティトーの死去で、民族や宗教の対立が表面化！</strong></span></h4>\n<p>そもそも、第一次世界大戦後に成立した時点で、<strong class=\"source-bold\">ユーゴスラヴィア（ユーゴ）</strong>は統一することに無理がある国だった。独立した時点で、ユーゴスラヴィアのなかには<strong class=\"source-bold\">6つの共和国</strong>があって、さらに「<strong class=\"source-bold\">東方正教会（ギリシア正教）、カトリック、イスラーム教徒</strong>」の3宗教の根深い対立があった。第二次世界大戦後は、パルチザン闘争の指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティトー</strong></span>のカリスマ性で統合していたけど、1980年に<strong class=\"source-bold\">ティトーが亡くなると対立が表面化</strong>した。それを「社会主義体制」で抑え込んでいたんだよ。</p>\n<p>そして<strong class=\"source-bold\">東欧革命</strong>で社会主義政権が次々と<ruby>崩壊<rt>ほうかい</rt></ruby>すると、ユーゴでも一党<ruby>独裁<rt>どくさい</rt></ruby>への批</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "492": "<h2>492</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>判が高まり、さらに<strong class=\"source-bold\">経済の悪化</strong>と失業者の増加で<strong class=\"source-bold\">宗教や民族の対立が激しくなった</strong>。だって、ユーゴスラヴィアって、セルビアが主導権を握って他の民族を支配する体制だったんだもん。こうして、反発した各共和国が独立を宣言したんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 4つの共和国が独立を宣言して、ユーゴスラヴィア内戦が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p>1991年6月、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スロヴェニア共和国</strong></span>（<strong class=\"source-bold\">カトリック</strong>）と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クロアティア共和国</strong></span>（<strong class=\"source-bold\">カトリック</strong>）が独立を宣言すると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>（セルビア正教会）を中心とする<strong class=\"source-bold\">ユーゴ連邦軍が軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア内戦</strong></span>が始まった。さらに、両国の独立を見た<strong class=\"source-bold\">マケドニア共和国</strong>（マケドニア正教会）が9月に独立を宣言（マケドニアは2019年に「<strong class=\"source-bold\">北マケドニア」と改称</strong>）、翌92年3月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span>も独立宣言を出した。内戦が始まったユーゴには、<strong class=\"source-bold\">国連平和維持軍（部隊）【PKF】</strong>が派遣され、<strong class=\"source-bold\">国連の仲介でとりあえず停戦が実現</strong>したんだけど、この時点で連邦に残ったのは<strong class=\"source-bold\">セルビアとモンテネグロ</strong>だけだった（<strong class=\"source-bold\">新ユーゴスラヴィア連邦</strong>）。でも、これだけじゃ終わらないよ……。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 3宗教が対立するボスニア・ヘルツェゴヴィナ。頼みの綱は「歴史の知恵」だ</strong></span></h4>\n<h4><strong class=\"source-bold\">〈ボスニア紛争〉</strong></h4>\n<p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ボスニア・ヘルツェゴヴィナ</strong></span></p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"gray-green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #859476;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">クロアティア軍</strong></span></td><td><span data-source-color=\"gray-green\" style=\"color:#859476\">介入 →</span></td><td><span data-source-border=\"gray-green\" data-source-border-style=\"dashed\" style=\"border:1px dashed #859476;border-radius:0.2em;padding:0 0.2em\">独立を目指す</span><br><span data-source-border=\"red\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #e52715;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">モスレム人</strong>（イスラーム教徒）</span><br><span data-source-color=\"gray-green\" style=\"color:#859476\">│</span><span data-source-color=\"red\" style=\"color:#e52715\">│</span><br><span data-source-border=\"gray-green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #859476;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">クロアティア人</strong>（カトリック）</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td><span data-source-border=\"gray-green\" data-source-border-style=\"dashed\" style=\"border:1px dashed #859476;border-radius:0.2em;padding:0 0.2em\">独立反対</span><br><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">セルビア人</strong>（ギリシア正教）</span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">← 介入</span></td><td><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">新ユーゴ軍</strong>（セルビア）</span></td></tr><tr><td></td><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">│</span><br><span data-source-border=\"green\" data-source-border-width=\"thick\" style=\"border:3px solid #315837;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ・EU</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">↗ NATO軍が介入</span></td><td></td><td></td><td></td></tr></tbody></table></div>\n<p>独立を達成した国のうち、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span>では3つの民族の間で<strong class=\"source-bold\">ボスニア紛争</strong>が起きたんだ。最大多数（約4割）を占めるイスラーム教徒（モスレム人）、約3割のセルビア人、そして2割弱のクロアティア人が激しい戦闘を繰り広げたんだけど、特に「<strong class=\"source-bold\">独立に反対するセルビア人</strong>」に対して、「<strong class=\"source-bold\">独立を目指すイスラーム教徒とクロアティア人</strong>」が連携し、それに<strong class=\"source-bold\">新ユーゴ連邦軍（セルビア軍）</strong>と<strong class=\"source-bold\">クロアティア共和国軍</strong>が介入して、壮絶な内戦になったんだ。国連による経済<ruby>制裁<rt>せいさい</rt></ruby>も効果はなく、<strong class=\"source-bold\">アメリカやEUが反セルビアで紛争に介入</strong>し、何度か和平提案がお</p>",
  "493": "<h2>493</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">地域紛争・民族紛争の激化</u></p></blockquote>\n<p>こなわれたけど、ついにアメリカを中心とする<strong class=\"source-bold\"><ruby>NATO<rt>ナトー</rt></ruby>軍が出動</strong>した。そして1995年にはアメリカ大統領<strong class=\"source-bold\">クリントン</strong>の圧力もあって（普通は“仲介”っていうね）、<strong class=\"source-bold\">ボスニア和平協定</strong>が結ばれ、「<strong class=\"source-bold\">ボスニア連邦</strong>」（イスラーム教徒とクロアティア人）と「<strong class=\"source-bold\">セルビア人共和国</strong>」という、「2つの主体」からなる連合国家になった。</p>\n<p>激しい内戦を経験したけど、この地域は<strong class=\"source-bold\">オスマン帝国やオーストリアに支配されていた時期にも、3民族共存の知恵を出し合ってきた</strong>。例えば、使う文字（キリル文字orラテン文字）は違っても、話す言語（セルビア＝クロアティア語）は同じ。きっと、これまでの「歴史の知恵」でうまくまとまれるんじゃないかな。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ セルビア内のコソヴォ自治州の独立運動から、コソヴォ紛争が起きた！</strong></span></h4>\n<p>ボスニア紛争が終わり、今度は<strong class=\"source-bold\">セルビア共和国</strong>内の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コソヴォ自治州</strong></span>で<strong class=\"source-bold\">アルバニア系住民（イスラーム教徒）の独立運動</strong>が起きると、セルビアの<strong class=\"source-bold\">ミロシェヴィッチ</strong>大統領はコソヴォ自治州の<strong class=\"source-bold\">アルバニア人への<ruby>弾圧<rt>だんあつ</rt></ruby></strong>を強め、全面的な武力衝突になった。しかも、ミロシェヴィッチはアルバニア人に対する「<strong class=\"source-bold\">民族<ruby>浄化<rt>じょうか</rt></ruby></strong>」（敵対する民族を<ruby>虐殺<rt>ぎゃくさつ</rt></ruby>や文化<ruby>抹消<rt>まっしょう</rt></ruby>などで抑圧すること）をおこなったから、欧米諸国は「<ruby>人道<rt>じんどう</rt></ruby>に反する」との批判を強め、ついに1999年、<strong class=\"source-bold\">クリントン</strong>大統領は<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>の決議がないままNATO軍によるセルビア空爆</strong>をおこなったんだ。これが、のちのアメリカの単独行動主義への布石になっちゃうんだけどね。</p>\n<p>こうして2000年には<strong class=\"source-bold\">ミロシェヴィッチ政権が<ruby>崩壊<rt>ほうかい</rt></ruby></strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コソヴォ紛争</strong></span>は終結したよ。そして、ミロシェヴィッチは人道に対する犯罪人として国際刑事裁判法廷で裁かれ、収監中に死亡したんだ。</p>\n<p>そして現在、<strong class=\"source-bold\">ユーゴスラヴィアという国はない</strong>よね。新ユーゴも2006年に<strong class=\"source-bold\">モンテネグロが分離独立</strong>して崩壊し、さらに2008年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コソヴォ共和国</strong></span>も独立を宣言した。コソヴォは<strong class=\"source-bold\">米英仏独日</strong>などを中心に、すでに<strong class=\"source-bold\">国連加盟国の過半数が承認</strong>しているんだけど、まだ<strong class=\"source-bold\">ロシア、中国、セルビアなどが承認していない</strong>んだ。</p>\n<h3><span data-source-border=\"pink\" data-source-border-shape=\"scalloped\" data-source-border-style=\"double\" style=\"border:3px double #f0a0a0;border-radius:1em;padding:0 0.3em\"><strong class=\"source-bold\">＋<span data-source-color=\"red\" style=\"color:#e52715\">α</span> <u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\">ちょっと寄り耳</u>⬆</strong></span></h3>\n<blockquote><p>コソヴォ問題は、「セルビア人」「アルバニア人」の歴史的なアイデンティティに深くかかわるから、単なる領土の取り合い以上に激しい対立になったんだ。</p>\n<p>コソヴォは、セルビア人にとっては中世セルビア王国の中心地だから、彼らの栄光の土地だよ。しかも、コソヴォの戦いで敗れてオスマン帝国の支配に屈したから、民族の<ruby>屈辱<rt>くつじょく</rt></ruby>の地でもある。「二度とコソヴォを取られるわけにはいかない！」という意識はあるだろうね。</p>\n<p>一方、オスマン帝国は、民族の空白地となったコソヴォに、ムスリムに改宗させたアルバニア人を入植させた。このアルバニア人たちが、19世紀に入ってコソヴォを拠点に独立運動を進めたから、アルバニア人にとってのコソヴォは、独立を<ruby>象徴<rt>しょうちょう</rt></ruby>する土地なんだよ。どちらにとっても、歴史的に譲れない土地だからこそ、対立は根深いよ。</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "494": "<h2>494</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈混迷する中東情勢〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>冷戦<rt>れいせん</rt></ruby>終結後のイスラエルとパレスチナは、「<ruby>報復<rt>ほうふく</rt></ruby>の応酬」だ</strong></span></h4>\n<p>冷戦終結後の<strong class=\"source-bold\">中東和平をめぐる問題は進展と挫折の繰り返し</strong>だよ。イスラエルでは、<strong class=\"source-bold\">右派（リクード）</strong>政権と<strong class=\"source-bold\">左派（労働党）</strong>政権がたびたび交替して、そのたびに「<strong class=\"source-bold\">労働党政権が和平を進め、リクード政権が和平交渉を<ruby>潰<rt>つぶ</rt></ruby>す</strong>」が繰り返されている。そして2001年に成立したリクードの<strong class=\"source-bold\">シャロン</strong>政権によるパレスチナへの強硬政策で状況が悪化し、同時多発テロ事件 <strong class=\"source-bold\">【9.11事件】</strong>以降のアメリカのブッシュ（子）大統領の対イラク政策も、問題を複雑にしたんだ。</p>\n<p><ruby>湾岸<rt>わんがん</rt></ruby>戦争でもそうだったんだけど、イラクの<strong class=\"source-bold\">サダム＝フセイン</strong>は「<strong class=\"source-bold\">アメリカvs. イラク</strong>」<strong class=\"source-bold\">を</strong>「<strong class=\"source-bold\">イスラエルvs. パレスチナ」にすり替えようとした</strong>から、米大統領<strong class=\"source-bold\">ブッシュ</strong>は、2002年に<strong class=\"source-bold\">中東和平ロードマップ</strong>を発表したんだけど、イスラエルとパレスチナの溝は全く埋まらなかった。だって、イスラエルは<strong class=\"source-bold\">パレスチナ人指導者の暗殺</strong>や<strong class=\"source-bold\">パレスチナ人地域への新たな入植、パレスチナ人自治区の<ruby>隔離<rt>かくり</rt></ruby></strong>（通称“<strong class=\"source-bold\"><ruby>壁<rt>かべ</rt></ruby></strong>”の建設）などの強行策を続けたんだもん。しかも、パレスチナ側も<strong class=\"source-bold\"><ruby>自爆<rt>じばく</rt></ruby>テロで対抗</strong>したから、報復に次ぐ報復で和平はどんどん遠のいている。さらに、アメリカの<strong class=\"source-bold\">ブッシュ大統領がイラク攻撃</strong>を始めると、中東問題の解決はますます難しくなったんだよ。</p>\n<p>そして2004年にPLOの議長<strong class=\"source-bold\">アラファトが死去</strong>すると、イスラーム原理主義の過激派「<strong class=\"source-bold\">ハマス</strong>」が台頭して、自爆テロなどをますます激化させていたんだ。</p>\n<blockquote><p>パレスチナ問題は、アメリカのイラク攻撃で、余計にややこしくなったんだ！ 解決する道はどこにあるのかな？</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「アラブの春」で混迷する中東情勢。パレスチナ問題の解決が必要だ！</strong></span></h4>\n<p>2011年以降<strong class=\"source-bold\">中東から北アフリカで起きた民主化運動</strong>、いわゆる「<strong class=\"source-bold\">アラブの春</strong>」で、中東情勢は混迷したんだ。1980年代まで、この地域の政治は「<strong class=\"source-bold\">米ソ冷戦</strong>」と「<strong class=\"source-bold\">パレスチナ問題</strong>」に左右された。各国の選択肢は「イスラエルを承認してアメリカから経済的・軍事的な支援を受ける」のか、逆に「反米・反イスラエル路線をとってソ連から支援を受ける」のか、それこそ「反米・反ソ・反イスラエルで別の道を進む」というのもありうる。もちろん、国ごとに「政府」「軍」「民衆」の立場がそれぞれ違うんだけど、民主化運動が起きた国では、<strong class=\"source-bold\">政府が「イスラーム教と距離を置き、欧米各国とは友好的」</strong>になって<ruby>独裁<rt>どくさい</rt></ruby>を維持し、<strong class=\"source-bold\">民主化運動が「イスラーム原理主義の影響を受ける」</strong>ことが多かった。つまり、「<strong class=\"source-bold\">世俗化（政教分離）vs. イスラーム</strong>」という考え方の違いが対立を招いたんだよ。</p>",
  "495": "<h2>495</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">地域紛争・民族紛争の激化</u></p></blockquote>\n<h4><strong class=\"source-bold\">〈「アラブの春」〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">チュニジア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ジャスミン革命［2011.1］</span></td></tr><tr><td><strong class=\"source-bold\">リビア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">カダフィ政権崩壊［2011.8］</span></td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ムバラク政権崩壊［2011.2］</span></td></tr><tr><td><strong class=\"source-bold\">シリア</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">民主化デモ［2011.4］ →内戦となる</span></td></tr></tbody></table></div>\n<blockquote><p>独裁政権が次々倒れたけど、混乱は続いているよ</p></blockquote>\n<p>「アラブの春」で最初に政権交代が起きたのが、<strong class=\"source-bold\">チュニジア</strong>だ。チュニジアでは1987年に<ruby>無血<rt>むけつ</rt></ruby>クーデタでベン＝アリーが政権を奪い、イスラーム主義組織を<ruby>弾圧<rt>だんあつ</rt></ruby>して<ruby>独裁<rt>どくさい</rt></ruby>を続けていた。でも時代が変わったんだね。スマートフォンの普及でみんなが使い始めた<strong class=\"source-bold\">SNSを通じたデモの呼びかけ</strong>で、民主化運動が急激に拡大し、2011年ついに<strong class=\"source-bold\">独裁政権が<ruby>崩壊<rt>ほうかい</rt></ruby></strong>したんだ（<strong class=\"source-bold\">ジャスミン革命</strong>）。そして、革命後の選挙では<strong class=\"source-bold\"><ruby>穏健<rt>おんけん</rt></ruby>なイスラーム政党が勝った</strong>んだけど、世俗派（政教分離を主張するグループ）の野党指導者がたびたび暗殺されるなど、混迷が続いたんだ。</p>\n<p>続いて崩壊したのが、<strong class=\"source-bold\">エジプトのムバラク</strong>政権だよ。ムバラクは1981年に大統領となって独裁体制をつくると、基本的には「<strong class=\"source-bold\">親米・親イスラエル</strong>」路線をとっていた。エジプトも、「<strong class=\"source-bold\">政教分離」で政治をやっていたムバラク</strong>に対し、穏健なイスラーム原理主義の「<strong class=\"source-bold\">ムスリム<ruby>同胞団<rt>どうほうだん</rt></ruby></strong>」（彼らは、最終的にはイスラーム国家をつくりたい！）が反対して、彼らの影響力で大規模なデモが続いたんだ。ちなみに、<strong class=\"source-bold\">ムスリム同胞団ができたのは1928年</strong>だ。以後、<strong class=\"source-bold\">王政、ナセル、サダト、ムバラクに次々と反対</strong>し、ついに2011年に<strong class=\"source-bold\">ムバラク政権を崩壊に追い込んだ</strong>。その後、ムスリム同胞団（自由と公正党）が支持する<strong class=\"source-bold\">モルシ</strong>が大統領になったんだけど、今度は<strong class=\"source-bold\">イスラーム政策に反発した軍部</strong>が2013年にクーデタで<strong class=\"source-bold\">モルシ大統領を解任</strong>、再び「軍部」による政治に戻ってしまった。つまり「<strong class=\"source-bold\">イスラーム化を中断しよう</strong>」ってことだ。</p>\n<p><strong class=\"source-bold\">リビア</strong>では、1969年から<strong class=\"source-bold\">パン＝アラブ主義</strong>を唱える<strong class=\"source-bold\">カダフィ</strong>が独裁を続け、イラク戦争の前までは、武器の密輸にかかわったり、<ruby>核<rt>かく</rt></ruby>開発疑惑があったりする反米の国だったから、アメリカに「テロ支援国家」に指定されていた。でも、<strong class=\"source-bold\">イラク戦争でフセイン政権が<ruby>潰<rt>つぶ</rt></ruby>された</strong>のを見て焦ったカダフィは、2003年には<strong class=\"source-bold\">核開発を<ruby>放棄<rt>ほうき</rt></ruby>するかわりにアメリカとの関係を改善</strong>したんだ。ただ、独裁は続いていたから、2011</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "496": "<h2>496</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第26回</strong></span> 冷戦終結後の世界（1990〜）</p></blockquote>\n<p>年にカダフィ政権に対して反政府デモが起きた。これに対し、カダフィは外国人<ruby>傭<rt>よう</rt></ruby><ruby>兵<rt>へい</rt></ruby>を使って民主化運動を激しく<ruby>弾圧<rt>だんあつ</rt></ruby>！ しかし、<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>決議</strong>によって<strong class=\"source-bold\"><ruby>NATO<rt>ナトー</rt></ruby>を中心とする多国籍軍が攻撃</strong>し、<strong class=\"source-bold\">カダフィ政権は<ruby>崩壊<rt>ほうかい</rt></ruby></strong>した。その後カダフィは、反対派の民兵につかまって殺されたんだよ。哀しい<ruby>独裁<rt>どくさい</rt></ruby>者の末路だな……。</p>\n<p>そして、もっとも混迷しているのが<strong class=\"source-bold\">シリア</strong>だよ。2011年、父親の代から長期の独裁を続けていた<strong class=\"source-bold\">アサド</strong>大統領に対して、民主化を要求するデモが起きた。最初は平和的な抗議だったんだけど、一部の過激な勢力が武装したため政府軍が激しく弾圧して、内戦になった。そして、<strong class=\"source-bold\">反政府軍</strong>を<strong class=\"source-bold\">アメリカや西欧諸国</strong>などが、<strong class=\"source-bold\">アサド政権</strong>を<strong class=\"source-bold\">イランさらにはロシア</strong>などが支援し、トルコは国内のクルド人問題からシリアのクルド人勢力を攻撃して、さらに周辺の過激な<strong class=\"source-bold\">イスラーム武装組織</strong>も入ってきて内戦は泥沼化した。さらに2014年になると、隣国のイラク北部から興ったスンナ派の過激派武装集団「IS（Islamic State）」が一時<strong class=\"source-bold\">シリアとイラクにまたがる地域を制圧</strong>したから、ますます複雑な情勢になったんだ（ISはすでにほぼ壊滅）。その後、アサド政権の政府軍が優勢な状況になったけど、完全に戦闘が終わったわけじゃない。そして、<strong class=\"source-bold\">戦闘を逃れた多数の難民が、今も国外に避難している</strong>状態だ。シリアの問題は、パレスチナ問題の縮図みたいになっているから、解決するのはなかなか難しいね。</p>\n<p><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">シリア</strong></span></p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"red\" data-source-border-shape=\"circle\" style=\"border:2px solid #e52715;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン</strong></span></span><br><span data-source-border=\"red\" data-source-border-shape=\"circle\" style=\"border:2px solid #e52715;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span></span></td><td><span data-source-color=\"red\" data-source-from=\"イラン\" data-source-to=\"アサド政権\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"none\" style=\"color:#e52715\">━</span><br><span data-source-color=\"red\" data-source-from=\"ロシア\" data-source-to=\"アサド政権\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"none\" style=\"color:#e52715\">╱</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アサド政権</strong></span></span></td><td><span data-source-color=\"black\" data-source-from=\"アサド政権\" data-source-to=\"IS\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"both\" style=\"color:#001000\">↔</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">IS</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">（ほぼ壊滅）</span></span></td></tr><tr><td><span data-source-color=\"black\" data-source-from=\"ロシア\" data-source-to=\"トルコ\" data-source-line-style=\"dashed\" data-source-line-width=\"thick\" data-source-arrowheads=\"none\" style=\"color:#001000\"><strong class=\"source-bold\">停戦交渉などで連携</strong></span></td><td></td><td><span data-source-color=\"black\" data-source-from=\"アサド政権\" data-source-to=\"クルド人勢力\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"both\" style=\"color:#001000\">↕</span></td><td><span data-source-color=\"black\" data-source-from=\"アサド政権\" data-source-to=\"反政府勢力\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"both\" style=\"color:#001000\">⤡</span></td><td><span data-source-color=\"black\" data-source-from=\"IS\" data-source-to=\"反政府勢力\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"both\" style=\"color:#001000\">↕</span></td></tr><tr><td></td><td></td><td><span data-source-border=\"gray-green\" data-source-border-style=\"solid\" style=\"border:1px solid #859476;border-radius:0.2em;padding:0 0.2em\"><span data-source-color=\"gray-green\" style=\"color:#859476\"><strong class=\"source-bold\">クルド人勢力</strong></span></span></td><td></td><td><span data-source-border=\"gray-green\" data-source-border-style=\"solid\" style=\"border:1px solid #859476;border-radius:0.2em;padding:0 0.2em\"><span data-source-color=\"gray-green\" style=\"color:#859476\"><strong class=\"source-bold\">反政府勢力</strong></span></span></td></tr><tr><td></td><td></td><td><span data-source-color=\"black\" data-source-from=\"クルド人勢力\" data-source-to=\"トルコ\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"both\" style=\"color:#001000\">↕</span></td><td><span data-source-color=\"gray-green\" data-source-from=\"アメリカ・西欧\" data-source-to=\"クルド人勢力\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"none\" style=\"color:#859476\">╲</span> <span data-source-color=\"gray-green\" data-source-from=\"トルコ\" data-source-to=\"反政府勢力\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"none\" style=\"color:#859476\">╱</span></td><td><span data-source-color=\"gray-green\" data-source-from=\"アメリカ・西欧\" data-source-to=\"反政府勢力\" data-source-line-style=\"solid\" data-source-line-width=\"thick\" data-source-arrowheads=\"none\" style=\"color:#859476\">│</span></td></tr><tr><td></td><td></td><td><span data-source-border=\"gray-green\" data-source-border-style=\"solid\" data-source-border-shape=\"circle\" style=\"border:1px solid #859476;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><span data-source-color=\"gray-green\" style=\"color:#859476\"><strong class=\"source-bold\">トルコ</strong></span></span></td><td></td><td><span data-source-border=\"gray-green\" data-source-border-style=\"solid\" data-source-border-shape=\"circle\" style=\"border:1px solid #859476;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><span data-source-color=\"gray-green\" style=\"color:#859476\"><strong class=\"source-bold\">アメリカ・西欧</strong></span></span></td></tr></tbody></table></div>\n<p>よーし、残すは最後の年号checkだけだよ！</p>\n<h3><span data-source-color=\"green\" data-source-outline-color=\"black\" style=\"color:#859476;text-shadow:1px 0 #001000,-1px 0 #001000,0 1px #001000,0 -1px #001000\"><strong class=\"source-bold\">‼</strong></span> <span data-source-color=\"red\" data-source-background=\"white\" data-source-border-shape=\"circle\" style=\"color:#e52715;background-color:#fff;border-radius:50%;padding:0 0.1em\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">のツボ</span></h3>\n<div class=\"source-frame\" data-source-border=\"pink\" data-source-border-pattern=\"diagonal-lines\" data-source-corner-decoration=\"brown-triangles\" style=\"border:4px solid #f0a0a0;border-image:repeating-linear-gradient(135deg,#fff 0 3px,#f0a0a0 3px 4px) 4;padding:0 0.2em\"><ul><li><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">マーストリヒト条約</strong>［<span data-source-color=\"red\" style=\"color:#e52715\">1992</span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>国<rt>92</rt></ruby></span>みんな EU入る）</li><li><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">同時多発テロ事件【9.11事件】</strong>［<span data-source-color=\"red\" style=\"color:#e52715\">2001</span>］（テロで犠牲の <span data-source-color=\"red\" style=\"color:#e52715\"><ruby>ツ<rt>2</rt></ruby><ruby>レ<rt>0</rt></ruby><ruby>を<rt>0</rt></ruby><ruby><ruby>悼<rt>1</rt></ruby><rt data-source-position=\"below\" style=\"ruby-position:under\"><span data-source-color=\"red\" style=\"color:#e52715\">イ</span><span data-source-color=\"black\" style=\"color:#001000\">タ</span></rt></ruby></span>んで）</li><li><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">イラク戦争</strong>［2<span data-source-color=\"red\" style=\"color:#e52715\">003</span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><ruby>オ<rt>0</rt></ruby><ruby>レ<rt>0</rt></ruby><ruby>様<rt>3</rt></ruby></span>ブッシュが イラク攻撃）</li></ul></div>\n<p>ここまできたみんな、本当に<ruby>頑張<rt>がんば</rt></ruby>ったね。こうなったら、世界史を得点源にして志望校合格だー！ お疲れ様でした。</p>",
  "497": "<h2>497</h2>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" data-source-border-shape=\"circle\" style=\"color:#fff;background-color:#a43725;border-radius:50%;padding:0.15em 0.3em;display:inline-block\">10</span></h3>\n<h4><strong class=\"source-bold\">〜日本の安全保障と沖縄の米軍基地〜</strong></h4>\n<div class=\"source-frame\" data-source-border=\"light-brown\" data-source-border-width=\"thick\" data-source-background=\"white\" data-source-corner-decoration=\"fold-lines\" style=\"border:7px solid #e9dfd8;background-color:#fff;padding:0 0.3em\"><p> <ruby>冷戦<rt>れいせん</rt></ruby>下での日本の安全保障はアメリカに依存していたけど、1970年代にアメリカの<ruby>覇権<rt>はけん</rt></ruby>が揺らぎ始めると、<strong class=\"source-bold\">日米の協力関係を強化</strong>する方向に変わっていき、1978年には自衛隊とアメリカ軍の共同訓練が始まったんだ。でも、<strong class=\"source-bold\">冷戦の終結</strong>後は、日本の政策もこれまでどおりというわけにはいかないよね！。</p>\n<p>1991年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>湾岸<rt>わんがん</rt></ruby>戦争</strong></span>では、国連<strong class=\"source-bold\">安保理の決議に基づく多国籍軍を派遣</strong>したけど、憲法の規定で<strong class=\"source-bold\">海外への自衛隊派兵が難しかった日本</strong>は、130億ドルも<strong class=\"source-bold\">財政支援をした</strong>んだけど、戦後に評価はされなかった。これ以降、日本も<strong class=\"source-bold\">国連主導の平和維持活動（PKO）には積極的に参加</strong>していくよ。1992年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際平和協力法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">PKO協力法</strong></span>】</strong>を成立させ、翌年、<strong class=\"source-bold\">自衛隊を国連カンボジア<ruby>暫定統治<rt>ざんていとうち</rt></ruby>機構【UNTAC】に派遣</strong>したんだ。</p>\n<p>さらに、アメリカの対テロ戦争に協力するため、<strong class=\"source-bold\"><ruby>小泉純一郎<rt>こいずみじゅんいちろう</rt></ruby></strong>内閣は<strong class=\"source-bold\">特別措置法を制定</strong>して<strong class=\"source-bold\">自衛隊を海外に派遣</strong>し、アメリカのアフガニスタン戦争ではインド洋での給油活動を、<strong class=\"source-bold\">イラクでは戦後の<ruby>復興<rt>ふっこう</rt></ruby>支援をおこなう</strong>ために、自衛隊を派遣したんだ。そして2015年には<strong class=\"source-bold\"><ruby>安倍晋三<rt>あべしんぞう</rt></ruby></strong>内閣が安全保障法制によって<strong class=\"source-bold\">集団的自衛権に基づいて海外で武力行使をすることを容認</strong>したんだ。これについては、現行憲法のもとで本当に認められるものかどうかの議論が起こったけど、そのあたりがうやむやにされた感は否めないかな。</p>\n<p>一方で、日米の安全保障協力が強化されるなかで、負担が増加しているのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">沖縄</strong></span>だ。国土の1％に満たない面積の<strong class=\"source-bold\">沖縄県に全国の米軍基地と関連施設の面積の約7割が集中</strong>していて、例えば、沖縄本島の面積の約15％を米軍基地が占めている。単に面積の問題にとどまらず、1995年の<strong class=\"source-bold\">アメリカ海兵隊員による女子小学生への暴行事件</strong>、2004年の沖縄国際大学への米軍ヘリ墜落事件など、現在まで<strong class=\"source-bold\">米軍やその関係者による事件</strong>がいくつも起きている。日米両政府は1996年に<strong class=\"source-bold\"><ruby>普天間<rt>ふてんま</rt></ruby>海兵隊基地の返還</strong>に合意したものの、<strong class=\"source-bold\">移設先とされたのは同じ沖縄本島内の<ruby>名護<rt>なご</rt></ruby>市<ruby>辺野古<rt>へのこ</rt></ruby></strong>であり、いまだに沖縄県民に負担が集中している。日本の安全保障を考える際には、こうした現状もきちんと認識したうえで、米軍基地の問題だけではなく、自衛隊のあり方も含めて国民的な議論をする必要があるんじゃないかな。</p>\n<p>ただ、「米軍がいなくなればいい」というような単純な話ではない。例えば沖縄近海の<strong class=\"source-bold\"><ruby>尖閣<rt>せんかく</rt></ruby>諸島</strong>は1895年に日本領となったけど、1960年代になってその付近に<strong class=\"source-bold\">石油などの資源が発見</strong>され、また豊かな漁場にも近いことから<strong class=\"source-bold\">中国や台湾が領有権を主張し始めた</strong>。近年では周辺に中国の艦船が頻繁に現れている。また、韓国が不法占拠を続ける島根県の<strong class=\"source-bold\"><ruby>竹島<rt>たけしま</rt></ruby></strong>をめぐる問題もあるね。 </p></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>"
};

